  {"id":"burgeon","word":"burgeon","ipa":"/ˈbɜːrdʒən/","senses":[{"pos":"v.","zh":"迅速发展；激增"}],"sceneHook":"burgeon fast","sceneHookZh":"迅速发展","collocations":["burgeon fast","burgeoning market","burgeoning demand"],"examples":[{"en":"Small tech startups continue to burgeon fast across the city.","zh":"小型科技初创公司继续在全城迅速发展。","source":"ClawWords Editorial","mt":true},{"en":"We are now seeing governments pledge support to national AI initiatives and compete in a technological race to dominate the burgeoning machine-learning sector.","zh":"我们现在看到各国政府承诺支持国家人工智能计划，并在主导蓬勃发展的机器学习领域的科技竞赛中展开竞争。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"C1","zipf":3.12,"lists":["green"]},
  {"id":"easy-going","word":"easy-going","ipa":"/ˌiːziˈɡoʊɪŋ/","senses":[{"pos":"adj.","zh":"随和的；悠闲从容的"}],"sceneHook":"easy-going mentor","sceneHookZh":"随和导师","collocations":["easy-going mentor","easy-going attitude","easy-going lifestyle"],"examples":[{"en":"Our new manager is an easy-going mentor who listens patiently.","zh":"我们的新经理是一位耐心的、随和的导师。","source":"ClawWords Editorial","mt":true},{"en":"Students often adapt more smoothly to campus life when guided by easy-going teachers.","zh":"在随和的教师指导下，学生往往能更顺利地适应大学生活。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B2","zipf":3.45,"lists":["green"]},
  {"id":"consortium","word":"consortium","ipa":"/kənˈsɔːrtiəm/","senses":[{"pos":"n.","zh":"财团；联营企业；联合体"}],"sceneHook":"form consortium","sceneHookZh":"组建联合体","collocations":["form consortium","international consortium","banking consortium"],"examples":[{"en":"Several renewable energy firms agreed to form consortium for research.","zh":"几家可再生能源公司同意组建联合体开展研究。","source":"ClawWords Editorial","mt":true},{"en":"An international consortium of universities launched an extensive environmental study across maritime regions.","zh":"一个由多所大学组成的国际联合体在海洋区域启动了一项广泛的环境研究。","source":"IELTS","mt":true}],"color":"#D9822B","level":"C1","zipf":3.38,"lists":["green"]},
  {"id":"periodical","word":"periodical","ipa":"/ˌpɪriˈɑːdɪkl/","senses":[{"pos":"n.","zh":"期刊；杂志"},{"pos":"adj.","zh":"周期的；定期的"}],"sceneHook":"read periodical","sceneHookZh":"阅读期刊","collocations":["read periodical","academic periodical","periodical publication"],"examples":[{"en":"Students often go to the library to read periodical articles.","zh":"学生们经常去图书馆阅读期刊文章。","source":"ClawWords Editorial","mt":true},{"en":"The academic library subscribes to every major scientific periodical published in Europe.","zh":"该学术图书馆订阅了在欧洲出版的所有主要科学期刊。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.25,"lists":["green"]},
  {"id":"apace","word":"apace","ipa":"/əˈpeɪs/","senses":[{"pos":"adv.","zh":"迅速地；急速地"}],"sceneHook":"continue apace","sceneHookZh":"快速推进","collocations":["continue apace","grow apace","proceed apace"],"examples":[{"en":"Construction of the laboratory will continue apace despite heavy rain.","zh":"尽管下着大雨，实验室的施工仍将快速推进。","source":"ClawWords Editorial","mt":true},{"en":"Urban development and technological innovation have proceeded apace throughout the developing coastal areas.","zh":"在沿海发展中地区，城市发展和技术创新一直在快速推进。","source":"IELTS","mt":true}],"color":"#22A06B","level":"C2","zipf":2.68,"lists":["green"]},
  {"id":"delve","word":"delve","ipa":"/dɛlv/","senses":[{"pos":"v.","zh":"钻研；深入探索"}],"sceneHook":"delve into","sceneHookZh":"深入钻研","collocations":["delve into","delve deeply","delve beneath"],"examples":[{"en":"Scholars should delve into historical archives to uncover fresh facts.","zh":"学者们应当深入钻研历史档案以揭示新事实。","source":"ClawWords Editorial","mt":true},{"en":"Researchers must delve into various economic factors before presenting comprehensive recommendations to policymakers.","zh":"研究人员在向决策者提出全面建议之前，必须深入探究各项经济因素。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C1","zipf":3.24,"lists":["green"]},
  {"id":"regent","word":"regent","ipa":"/ˈriːdʒənt/","senses":[{"pos":"n.","zh":"摄政者；摄政王"}],"sceneHook":"appoint regent","sceneHookZh":"任命摄政王","collocations":["appoint regent","prince regent","board of regents"],"examples":[{"en":"The royal council decided to appoint regent during the monarch illness.","zh":"皇家议会决定在国王生病期间任命摄政王。","source":"ClawWords Editorial","mt":true},{"en":"Historical records show that the prince regent exerted considerable political influence over legislative reforms.","zh":"历史记录表明，摄政王对立法改革发挥了相当大的政治影响力。","source":"IELTS","mt":true}],"color":"#16A085","level":"C2","zipf":2.85,"lists":["green"]},
  {"id":"buckle","word":"buckle","ipa":"/ˈbʌkl/","senses":[{"pos":"v.","zh":"扣紧；变弯曲"},{"pos":"n.","zh":"带扣"}],"sceneHook":"buckle belt","sceneHookZh":"扣紧皮带","collocations":["buckle belt","buckle under pressure","fasten the buckle"],"examples":[{"en":"Remember to buckle belt securely before the plane begins to taxi.","zh":"飞机滑行前切记将皮带扣紧。","source":"ClawWords Editorial","mt":true},{"en":"Steel support beams may buckle under extreme temperatures generated during industrial fire outbreaks.","zh":"在工业火灾产生的高温下，钢支撑梁可能会发生弯曲。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.42,"lists":["green"]},
  {"id":"subliminal","word":"subliminal","ipa":"/ˌsʌbˈlɪmɪnl/","senses":[{"pos":"adj.","zh":"下意识的；潜意识的"}],"sceneHook":"subliminal message","sceneHookZh":"潜意识信息","collocations":["subliminal message","subliminal perception","subliminal advertising"],"examples":[{"en":"Viewers rarely notice any subliminal message placed inside the video.","zh":"观众很少注意到视频中放置的任何潜意识信息。","source":"ClawWords Editorial","mt":true},{"en":"Psychological experiments demonstrate that subliminal stimuli can subtly influence individual consumer choices.","zh":"心理学实验表明，潜意识刺激能微妙地影响个体消费者的选择。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"C1","zipf":2.95,"lists":["green"]},
  {"id":"rig","word":"rig","ipa":"/rɪɡ/","senses":[{"pos":"v.","zh":"操纵；装配"},{"pos":"n.","zh":"钻探设备；索具"}],"sceneHook":"oil rig","sceneHookZh":"钻油平台","collocations":["oil rig","rig the election","drilling rig"],"examples":[{"en":"Engineers inspected the offshore oil rig after the massive winter storm.","zh":"工程师在巨大的冬季风暴后检查了海上钻油平台。","source":"ClawWords Editorial","mt":true},{"en":"Environmental activists raised serious concerns regarding safety procedures implemented aboard the offshore drilling rig.","zh":"环保人士对海上钻井平台上执行的安全程序提出了严重关切。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":3.58,"lists":["green"]},
  {"id":"impart","word":"impart","ipa":"/ɪmˈpɑːrt/","senses":[{"pos":"v.","zh":"传授；告知；赋予"}],"sceneHook":"impart knowledge","sceneHookZh":"传授知识","collocations":["impart knowledge","impart flavor","impart wisdom"],"examples":[{"en":"Dedicated teachers strive to impart knowledge clearly to every student.","zh":"敬业的教师努力将知识清晰地传授给每位学生。","source":"ClawWords Editorial","mt":true},{"en":"Experienced university professors seek to impart analytical skills that enable students to evaluate arguments critically.","zh":"经验丰富的大学教授力求传授使学生能够批判性评估论点的分析技能。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"C1","zipf":3.1,"lists":["green"]},
  {"id":"fabrication","word":"fabrication","ipa":"/ˌfæbrɪˈkeɪʃn/","senses":[{"pos":"n.","zh":"捏造；制造；装配"}],"sceneHook":"metal fabrication","sceneHookZh":"金属制造","collocations":["metal fabrication","complete fabrication","fabrication facility"],"examples":[{"en":"The factory specializes in precision metal fabrication for aerospace components.","zh":"该工厂专门从事航空航天部件的精密金属制造。","source":"ClawWords Editorial","mt":true},{"en":"Advanced manufacturing technology has substantially reduced the costs associated with component fabrication.","zh":"先进的制造技术大幅降低了与零部件制造相关的成本。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C1","zipf":3.02,"lists":["green"]},
  {"id":"embankment","word":"embankment","ipa":"/ɪmˈbæŋkmənt/","senses":[{"pos":"n.","zh":"路堤；筑堤；水坝"}],"sceneHook":"river embankment","sceneHookZh":"河堤水坝","collocations":["river embankment","railway embankment","earth embankment"],"examples":[{"en":"Volunteers reinforced the river embankment before the spring flood arrived.","zh":"志愿者在春汛到来前加固了河堤。","source":"ClawWords Editorial","mt":true},{"en":"Local civil engineers reconstructed the crumbling railway embankment to prevent landslides during torrential rains.","zh":"当地土木工程师重建了破损的铁路路堤，以防止暴雨期间发生滑坡。","source":"IELTS","mt":true}],"color":"#D9822B","level":"C1","zipf":2.88,"lists":["green"]},
  {"id":"chink","word":"chink","ipa":"/tʃɪŋk/","senses":[{"pos":"n.","zh":"缝隙；微弱光线；叮当声"}],"sceneHook":"chink of light","sceneHookZh":"一线微光","collocations":["chink of light","chink in armor","slight chink"],"examples":[{"en":"A narrow chink of light slipped beneath the heavy curtains.","zh":"一线微光从厚重的窗帘下透了进来。","source":"ClawWords Editorial","mt":true},{"en":"The discovery of historical documents offered a chink of insight into ancient trading practices.","zh":"历史文献的发现为深入了解古代贸易实践提供了一丝契机。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"C2","zipf":2.76,"lists":["green"]},
  {"id":"iris","word":"iris","ipa":"/ˈaɪrɪs/","senses":[{"pos":"n.","zh":"虹膜；鸢尾属植物"}],"sceneHook":"iris scanner","sceneHookZh":"虹膜扫描仪","collocations":["iris scanner","purple iris","iris recognition"],"examples":[{"en":"Security guards activated the modern iris scanner at the main entrance.","zh":"安保人员在大门处启动了现代化的虹膜扫描仪。","source":"ClawWords Editorial","mt":true},{"en":"Biometric security systems often employ iris patterns because their intricate structures remain uniquely consistent over time.","zh":"生物识别安全系统常采用虹膜图案，因为其复杂的结构随着时间的推移保持独特的稳定性。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.32,"lists":["green"]},
  {"id":"epitomise","word":"epitomise","ipa":"/ɪˈpɪtəmaɪz/","senses":[{"pos":"v.","zh":"成为典范；概括"}],"sceneHook":"epitomise elegance","sceneHookZh":"尽显典雅","collocations":["epitomise elegance","epitomise style","epitomise success"],"examples":[{"en":"Her graceful movements truly epitomise elegance on the dance floor.","zh":"她在舞池中优雅的舞姿真正诠释了典雅。","source":"ClawWords Editorial","mt":true},{"en":"The architectural structure continues to epitomise modern minimalist principles admired by contemporary international designers.","zh":"该建筑结构继续体现了受到当代国际设计师推崇的现代极简主义原则。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C1","zipf":2.72,"lists":["green"]},
  {"id":"delinquency","word":"delinquency","ipa":"/dɪˈlɪŋkwənsi/","senses":[{"pos":"n.","zh":"违法行为；过失；失职"}],"sceneHook":"juvenile delinquency","sceneHookZh":"青少年犯罪","collocations":["juvenile delinquency","delinquency rate","combat delinquency"],"examples":[{"en":"Social programs strive to reduce juvenile delinquency in urban neighborhoods.","zh":"社会项目致力于减少城市社区中的青少年犯罪。","source":"ClawWords Editorial","mt":true},{"en":"Educational researchers examined various community initiatives designed to deter juvenile delinquency among vulnerable adolescents.","zh":"教育研究人员考察了旨在阻止脆弱青少年违法行为的各项社区倡议。","source":"IELTS","mt":true}],"color":"#16A085","level":"C1","zipf":2.92,"lists":["green"]},
  {"id":"grunt","word":"grunt","ipa":"/ɡrʌnt/","senses":[{"pos":"v.","zh":"咕哝；发呼噜声"},{"pos":"n.","zh":"呼噜声；咕哝"}],"sceneHook":"grunt softly","sceneHookZh":"轻声咕哝","collocations":["grunt softly","grunt in pain","give a grunt"],"examples":[{"en":"The tired worker could only grunt softly before closing his eyes.","zh":"疲惫的工人闭上眼前只能轻声咕哝一下。","source":"ClawWords Editorial","mt":true},{"en":"Athletes frequently grunt during intense physical exertion to regulate respiratory pressure and maximize muscular power.","zh":"运动员在剧烈体力消耗时经常发出呼噜声，以调节呼吸压力并最大化肌肉力量。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.18,"lists":["green"]},
  {"id":"stint","word":"stint","ipa":"/stɪnt/","senses":[{"pos":"n.","zh":"特定工作时期；定量"},{"pos":"v.","zh":"吝惜；节制"}],"sceneHook":"brief stint","sceneHookZh":"短暂任期","collocations":["brief stint","stint abroad","without stint"],"examples":[{"en":"After a brief stint at university, he joined the software firm.","zh":"在大学度过短暂的一段时光后，他加入了那家软件公司。","source":"ClawWords Editorial","mt":true},{"en":"Following a productive stint in corporate management, she pursued an academic career researching sustainable development.","zh":"在企业管理部门度过充实的一段任期后，她从事了研究可持续发展的学术生涯。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"C1","zipf":3.14,"lists":["green"]},
  {"id":"evacuate","word":"evacuate","ipa":"/ɪˈvækjuːeɪt/","senses":[{"pos":"v.","zh":"疏散；撤离；排空"}],"sceneHook":"evacuate residents","sceneHookZh":"疏散居民","collocations":["evacuate residents","evacuate the building","evacuate safely"],"examples":[{"en":"Emergency responders rushed to evacuate residents as the storm approached rapidly.","zh":"暴风雨迅速逼近时，应急响应人员急忙疏散居民。","source":"ClawWords Editorial","mt":true},{"en":"Randy Jacobs, a Southern California- based lawyer who has had to evacuate both his home and business to escape wildfires.","zh":"兰迪·雅各布斯是一位南加州律师，为了躲避野火，他不得不撤离住所和办公地点。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":3.48,"lists":["green"]},
  {"id":"federation","word":"federation","ipa":"/ˌfɛdəˈreɪʃn/","senses":[{"pos":"n.","zh":"联邦；同盟；联合会"}],"sceneHook":"trade federation","sceneHookZh":"同业联合会","collocations":["trade federation","sports federation","national federation"],"examples":[{"en":"Representatives from each company joined the regional trade federation last spring.","zh":"去年春天，各公司的代表加入了区域同业联合会。","source":"ClawWords Editorial","mt":true},{"en":"Waldron, chairman of the standards committee at the Glass and Glazing Federation, a British trade association, and standards development officer at Pilkington.","zh":"沃德伦是英国行业协会玻璃与上釉联合会标准委员会的主席，也是皮尔金顿公司的标准制定官员。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.75,"lists":["green"]},
  {"id":"seep","word":"seep","ipa":"/siːp/","senses":[{"pos":"v.","zh":"渗出；渗透"}],"sceneHook":"seep through","sceneHookZh":"渗透通过","collocations":["seep through","seep slowly","seep into"],"examples":[{"en":"Cold rainwater began to seep through the cracked basement wall.","zh":"冰冷的雨水开始透过破裂的地下室墙体渗入。","source":"ClawWords Editorial","mt":true},{"en":"Industrial pollutants can gradually seep into groundwater reserves, contaminating drinking supplies over prolonged periods.","zh":"工业污染物会逐渐渗入地下水储层，在较长时期内污染饮用水源。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C1","zipf":3.15,"lists":["green"]},
  {"id":"doctorate","word":"doctorate","ipa":"/ˈdɑːktərət/","senses":[{"pos":"n.","zh":"博士学位"}],"sceneHook":"earn doctorate","sceneHookZh":"获得博士学位","collocations":["earn doctorate","honorary doctorate","doctorate degree"],"examples":[{"en":"She worked diligently for years to earn doctorate in biological engineering.","zh":"她多年勤奋学习，获得了生物工程学博士学位。","source":"ClawWords Editorial","mt":true},{"en":"Marie Curie received her Doctorate of Science, and Marie and Pierre shared with Becquerel the Nobel Prize for Physics for the discovery of radioactivity.","zh":"玛丽·居里获得了科学博士学位，玛丽和皮埃尔因发现放射性而与贝克勒尔分享了诺贝尔物理学奖。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B2","zipf":3.3,"lists":["green"]},
  {"id":"internship","word":"internship","ipa":"/ˈɪntɜːrnʃɪp/","senses":[{"pos":"n.","zh":"实习期；实习工作"}],"sceneHook":"summer internship","sceneHookZh":"暑期实习","collocations":["summer internship","complete internship","paid internship"],"examples":[{"en":"He secured a competitive summer internship at a reputable tech corporation.","zh":"他在一家知名科技公司获得了一份竞争激烈的暑期实习。","source":"ClawWords Editorial","mt":true},{"en":"Participating in an overseas internship provides university undergraduates with valuable multicultural collaboration skills.","zh":"参加海外实习为大学本科生提供了宝贵的跨文化协作技能。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.52,"lists":["green"]},
  {"id":"muddle","word":"muddle","ipa":"/ˈmʌdl/","senses":[{"pos":"v.","zh":"弄乱；混淆"},{"pos":"n.","zh":"混乱；糊涂"}],"sceneHook":"muddle up","sceneHookZh":"弄乱混淆","collocations":["muddle up","muddle through","in a muddle"],"examples":[{"en":"Careless filing methods will muddle up these confidential client records.","zh":"粗心的归档方式会搞混这些机密客户记录。","source":"ClawWords Editorial","mt":true},{"en":"Some of you have asked about a guided tour but we find this rather muddles people.","zh":"你们中有些人询问是否有导游带领的参观，但我们发现这反而容易让人们感到混乱。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.2,"lists":["green"]},
  {"id":"abode","word":"abode","ipa":"/əˈboʊd/","senses":[{"pos":"n.","zh":"住所；寓所"}],"sceneHook":"humble abode","sceneHookZh":"简陋住所","collocations":["humble abode","permanent abode","place of abode"],"examples":[{"en":"The retired author welcomed close friends into his humble abode.","zh":"这位退休作家欢迎好友来到他的简陋寓所。","source":"ClawWords Editorial","mt":true},{"en":"Archaeological excavations reveal that prehistoric communities established their seasonal abode near fertile riverbanks.","zh":"考古发掘表明，史前群落通常在肥沃的河岸附近设立季节性住所。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C1","zipf":3.11,"lists":["green"]},
  {"id":"hose","word":"hose","ipa":"/hoʊz/","senses":[{"pos":"n.","zh":"软管；水管"},{"pos":"v.","zh":"用软管冲洗"}],"sceneHook":"garden hose","sceneHookZh":"花园软管","collocations":["garden hose","fire hose","hose down"],"examples":[{"en":"Connect the flexible garden hose before washing the muddy stone patio.","zh":"在冲洗泥泞的石板露台前，先接好柔软的花园软管。","source":"ClawWords Editorial","mt":true},{"en":"Firefighters swiftly attached the industrial water hose to extinguishing pumps during the unexpected warehouse blaze.","zh":"在意外发生的仓库大火中，消防队员迅速将工业水管连接到灭火泵上。","source":"IELTS","mt":true}],"color":"#16A085","level":"B1","zipf":3.65,"lists":["green"]},
  {"id":"disharmony","word":"disharmony","ipa":"/dɪsˈhɑːrməni/","senses":[{"pos":"n.","zh":"不和谐；不和；冲突"}],"sceneHook":"cause disharmony","sceneHookZh":"引发不和","collocations":["cause disharmony","social disharmony","marital disharmony"],"examples":[{"en":"Unfair workplace policies can quickly cause disharmony among dedicated team members.","zh":"不公平的职场政策会迅速在敬业的团队成员之间引发不和。","source":"ClawWords Editorial","mt":true},{"en":"Cultural misunderstandings can trigger acute social disharmony unless proactive dialogue is established across communities.","zh":"除非在各社区之间建立积极对话，否则文化误解可能会引发严重的社会不和。","source":"IELTS","mt":true}],"color":"#2980B9","level":"C1","zipf":2.55,"lists":["green"]},
  {"id":"pronounceable","word":"pronounceable","ipa":"/prəˈnaʊnsəbl/","senses":[{"pos":"adj.","zh":"读得出的；可发音的"}],"sceneHook":"easily pronounceable","sceneHookZh":"容易发音","collocations":["easily pronounceable","readily pronounceable","pronounceable name"],"examples":[{"en":"The brand chosen was simple and easily pronounceable for foreign customers.","zh":"所选品牌名称简单，对于外国顾客来说很容易发音。","source":"ClawWords Editorial","mt":true},{"en":"Linguists noted that inventing pronounceable brand names significantly facilitates global marketing campaigns.","zh":"语言学家指出，发明易于发音的品牌名称能显著促进全球营销推广。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":2.45,"lists":["green"]},
  {"id":"intercept","word":"intercept","ipa":"/ˌɪntərˈsɛpt/","senses":[{"pos":"v.","zh":"截击；拦截；截取"},{"pos":"n.","zh":"截击；截获"}],"sceneHook":"intercept signals","sceneHookZh":"截获信号","collocations":["intercept signals","intercept communication","intercept missile"],"examples":[{"en":"Military intelligence officers managed to intercept signals transmitted across borders.","zh":"军事情报官员设法截获了跨越边境传输的信号。","source":"ClawWords Editorial","mt":true},{"en":"Coastguard patrols intercepted several unauthorized cargo vessels operating without proper documentation.","zh":"海岸警卫队巡逻队拦截了数艘无有效证件航行的违规货船。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":3.22,"lists":["green"]},
  {"id":"illusion","word":"illusion","ipa":"/ɪˈluːʒn/","senses":[{"pos":"n.","zh":"错觉；幻觉；幻想"}],"sceneHook":"optical illusion","sceneHookZh":"视错觉","collocations":["optical illusion","shatter illusion","under the illusion"],"examples":[{"en":"The clever painting creates an optical illusion of endless depth.","zh":"这幅巧妙的画作营造出无尽深度的视错觉。","source":"ClawWords Editorial","mt":true},{"en":"Psychological experiments illustrate how optical illusions manipulate human sensory perception under changing light conditions.","zh":"心理学实验阐释了视错觉在光线变化条件下是如何操纵人类感官知觉的。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.75,"lists":["green"]},
  {"id":"vertebrate","word":"vertebrate","ipa":"/ˈvɜːrtɪbrət/","senses":[{"pos":"n.","zh":"脊椎动物"},{"pos":"adj.","zh":"有脊椎的"}],"sceneHook":"vertebrate species","sceneHookZh":"脊椎动物物种","collocations":["vertebrate species","vertebrate evolution","marine vertebrate"],"examples":[{"en":"Biologists discovered a rare vertebrate species living in the mountain cave.","zh":"生物学家在该山洞中发现了一种罕见的脊椎动物物种。","source":"ClawWords Editorial","mt":true},{"en":"They flew into sunny skies before any other vertebrate.","zh":"它们比任何其他脊椎动物都更早飞向阳光明媚的天空。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C1","zipf":2.92,"lists":["green"]},
  {"id":"trapeze","word":"trapeze","ipa":"/træˈpiːz/","senses":[{"pos":"n.","zh":"高空秋千；吊架"}],"sceneHook":"swing trapeze","sceneHookZh":"荡高空秋千","collocations":["swing trapeze","flying trapeze","trapeze artist"],"examples":[{"en":"Circus performers practice daily to swing trapeze smoothly across the arena.","zh":"杂技演员每天练习，以在表演场上平稳地荡高空秋千。","source":"ClawWords Editorial","mt":true},{"en":"Skilled acrobats performed aerial stunts on the flying trapeze without using protective nets.","zh":"熟练的杂技演员在没有使用保护网的情况下在飞行吊架上进行了高空特技表演。","source":"IELTS","mt":true}],"color":"#D9822B","level":"C1","zipf":2.82,"lists":["green"]},
  {"id":"divisional","word":"divisional","ipa":"/dɪˈvɪʒənl/","senses":[{"pos":"adj.","zh":"部门的；师的；分部的"}],"sceneHook":"divisional manager","sceneHookZh":"部门经理","collocations":["divisional manager","divisional office","divisional structure"],"examples":[{"en":"Every divisional manager must submit quarterly expenditure reports on time.","zh":"每位部门经理都必须按时提交季度支出报告。","source":"ClawWords Editorial","mt":true},{"en":"The multinational conglomerate restructured its divisional operations to improve responsiveness to local consumer demands.","zh":"这家跨国集团对其各部门的运营进行了重组，以提高对当地消费者需求的响应速度。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"C1","zipf":2.88,"lists":["green"]},
  {"id":"counsellor","word":"counsellor","ipa":"/ˈkaʊnsələr/","senses":[{"pos":"n.","zh":"顾问；辅导员；咨询师"}],"sceneHook":"career counsellor","sceneHookZh":"职业辅导员","collocations":["career counsellor","guidance counsellor","camp counsellor"],"examples":[{"en":"A student consulted the career counsellor about selecting suitable postgraduate courses.","zh":"一名学生向职业辅导员咨询了选择合适研究生课程的建议。","source":"ClawWords Editorial","mt":true},{"en":"University students facing academic stress are encouraged to seek guidance from a qualified psychological counsellor.","zh":"鼓励面临学业压力的大学生寻求合格心理咨询师的指导。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.32,"lists":["green"]},
  {"id":"wastage","word":"wastage","ipa":"/ˈweɪstɪdʒ/","senses":[{"pos":"n.","zh":"浪费；损耗；流失"}],"sceneHook":"reduce wastage","sceneHookZh":"减少损耗","collocations":["reduce wastage","food wastage","natural wastage"],"examples":[{"en":"Modern kitchens adopt strict inventory controls to reduce wastage significantly.","zh":"现代厨房采取严格的库存控制以显著减少损耗。","source":"ClawWords Editorial","mt":true},{"en":"Agricultural scientists introduced innovative storage techniques to minimize grain wastage during distribution cycles.","zh":"农业科学家引进了创新的储存技术，以尽量减少流通过程中的粮食损耗。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C1","zipf":2.85,"lists":["green"]},
  {"id":"decrepit","word":"decrepit","ipa":"/dɪˈkrɛpɪt/","senses":[{"pos":"adj.","zh":"老朽的；破旧的；衰弱的"}],"sceneHook":"decrepit building","sceneHookZh":"破旧建筑","collocations":["decrepit building","decrepit car","decrepit condition"],"examples":[{"en":"City planners decided to demolish the decrepit building after structural inspection.","zh":"城市规划者在结构检查后决定拆除那座破旧建筑。","source":"ClawWords Editorial","mt":true},{"en":"Local municipal authorities replaced decrepit public transport vehicles with energy-efficient electric buses.","zh":"当地市政部门用节能电动巴士替换了老旧的公共交通车辆。","source":"IELTS","mt":true}],"color":"#16A085","level":"C1","zipf":2.8,"lists":["green"]},
  {"id":"mastery","word":"mastery","ipa":"/ˈmæstəri/","senses":[{"pos":"n.","zh":"精通；熟练；掌控"}],"sceneHook":"complete mastery","sceneHookZh":"完全精通","collocations":["complete mastery","gain mastery","language mastery"],"examples":[{"en":"Years of dedicated practice gave him complete mastery over the instrument.","zh":"多年的专注练习使他完全精通了这门乐器。","source":"ClawWords Editorial","mt":true},{"en":"Achieving linguistic mastery demands consistent immersion in authentic communicative environments over several years.","zh":"达到语言上的熟练精通需要在真实的交流环境中持续沉浸数年之久。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.55,"lists":["green"]},
  {"id":"gloss","word":"gloss","ipa":"/ɡlɑːs/","senses":[{"pos":"n.","zh":"光泽；虚饰"},{"pos":"v.","zh":"使有光泽；掩饰"}],"sceneHook":"high gloss","sceneHookZh":"高光泽","collocations":["high gloss","lip gloss","gloss over"],"examples":[{"en":"The polished wooden table retained a beautiful high gloss for years.","zh":"抛光的木桌多年来一直保持着美丽的高光泽。","source":"ClawWords Editorial","mt":true},{"en":"Biographical accounts often gloss over personal controversies to present celebrated public figures favorably.","zh":"传记记述往往会掩盖个人的争议，以便向公众正面展示著名人物。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":3.4,"lists":["green"]},
  {"id":"suitably","word":"suitably","ipa":"/ˈsuːtəbli/","senses":[{"pos":"adv.","zh":"适宜地；相称地"}],"sceneHook":"suitably qualified","sceneHookZh":"符合资质","collocations":["suitably qualified","suitably dressed","suitably impressed"],"examples":[{"en":"Applicants must be suitably qualified to handle advanced laboratory procedures.","zh":"申请人必须具备合格资质以处理先进的实验室流程。","source":"ClawWords Editorial","mt":true},{"en":"Candidates who are suitably experienced can expect competitive salary packages within international consulting corporations.","zh":"经验相称的求职者可以期待在国际咨询公司中获得有竞争力的薪酬待遇。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":3.42,"lists":["green"]},
  {"id":"industrious","word":"industrious","ipa":"/ɪnˈdʌstriəs/","senses":[{"pos":"adj.","zh":"勤劳的；勤奋的"}],"sceneHook":"industrious student","sceneHookZh":"勤奋学生","collocations":["industrious student","industrious worker","industrious people"],"examples":[{"en":"The industrious student completed all research assignments well before deadlines.","zh":"这名勤奋的学生在截止日期前很久就完成了所有的研究作业。","source":"ClawWords Editorial","mt":true},{"en":"Economic historians argue that an industrious workforce contributed fundamentally to the industrial modernization of East Asia.","zh":"经济历史学家认为，勤劳的劳动力从根本上促进了东亚的工业现代化。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"C1","zipf":3.05,"lists":["green"]},
  {"id":"outpost","word":"outpost","ipa":"/ˈaʊtpoʊst/","senses":[{"pos":"n.","zh":"前哨基地；边远据点"}],"sceneHook":"remote outpost","sceneHookZh":"偏远前哨","collocations":["remote outpost","military outpost","trading outpost"],"examples":[{"en":"Scientists stationed at the remote outpost recorded daily meteorological measurements.","zh":"驻扎在偏远前哨基地的科学家每天记录气象测量数据。","source":"ClawWords Editorial","mt":true},{"en":"Early commercial companies maintained fortified trading outposts along uncharted river routes across North America.","zh":"早期的商业公司沿着北美洲未标定地图的河流路线维持着设防的贸易据点。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C1","zipf":3.25,"lists":["green"]},
  {"id":"expel","word":"expel","ipa":"/ɪkˈspɛl/","senses":[{"pos":"v.","zh":"开除；驱逐；排出"}],"sceneHook":"expel students","sceneHookZh":"开除学生","collocations":["expel students","expel diplomats","expel air"],"examples":[{"en":"Principals seldom expel students without conducting extensive behavioral reviews first.","zh":"校长在进行全面的行为评估之前很少开除学生。","source":"ClawWords Editorial","mt":true},{"en":"The governmental committee decided to expel foreign diplomats implicated in clandestine espionage activities.","zh":"政府委员会决定驱逐涉嫌参与秘密间谍活动的外国外交官。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B2","zipf":3.35,"lists":["green"]},
  {"id":"dedicate","word":"dedicate","ipa":"/ˈdɛdɪkeɪt/","senses":[{"pos":"v.","zh":"奉献；致力于；题献"}],"sceneHook":"dedicate time","sceneHookZh":"投入时间","collocations":["dedicate time","dedicate life","dedicate to"],"examples":[{"en":"Volunteers dedicate time each weekend to assist elderly community residents.","zh":"志愿者每个周末都投入时间来帮助社区里的老年居民。","source":"ClawWords Editorial","mt":true},{"en":"The most important part of blindfold chess for me is that I have found the one thing that I can fully dedicate myself to.","zh":"对我来说盲棋最重要的部分在于，我找到了那件能够让我全身心投入的事情。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.85,"lists":["green"]},
  {"id":"astrology","word":"astrology","ipa":"/əˈstrɑːlədʒi/","senses":[{"pos":"n.","zh":"占星术；占星学"}],"sceneHook":"study astrology","sceneHookZh":"研究占星学","collocations":["study astrology","western astrology","astrology chart"],"examples":[{"en":"Many curious people study astrology to understand personal personality traits.","zh":"许多好奇的人研究占星学以了解个人的性格特质。","source":"ClawWords Editorial","mt":true},{"en":"Today, people still look to stars or genes, astrology or genetics, in the hope of finding the source of exceptional abilities or personal characteristics.","zh":"今天，人们仍然寄望于星辰或基因，占星学或遗传学，希望借此找到卓越才能或个人特征的源头。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.38,"lists":["green"]},
  {"id":"dub","word":"dub","ipa":"/dʌb/","senses":[{"pos":"v.","zh":"起绰号；配音"}],"sceneHook":"dub film","sceneHookZh":"为电影配音","collocations":["dub film","dub into English","dub knight"],"examples":[{"en":"Technicians worked through the night to dub film into English.","zh":"技术人员彻夜工作，将电影配音为英语。","source":"ClawWords Editorial","mt":true},{"en":"Cultural historians dubbed the twentieth century the era of mass media expansion and democratic transformation.","zh":"文化历史学家把二十世纪称为大众媒体扩张与民主转型的时代。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B2","zipf":3.48,"lists":["green"]},
  {"id":"discretion","word":"discretion","ipa":"/dɪˈskrɛʃn/","senses":[{"pos":"n.","zh":"谨慎；斟酌决定的自由"}],"sceneHook":"exercise discretion","sceneHookZh":"谨慎行事","collocations":["exercise discretion","sole discretion","with discretion"],"examples":[{"en":"Senior managers must exercise discretion when handling sensitive financial transactions.","zh":"高级经理在处理敏感财务交易时必须谨慎行事。","source":"ClawWords Editorial","mt":true},{"en":"Judges are granted substantial judicial discretion when determining rehabilitation sentences for juvenile offenders.","zh":"法官在确定少年犯的感化改造刑期时被赋予了相当大的司法裁量权。","source":"IELTS","mt":true}],"color":"#16A085","level":"C1","zipf":3.55,"lists":["green"]},
  {"id":"attest","word":"attest","ipa":"/əˈtɛst/","senses":[{"pos":"v.","zh":"证实；证明；作证"}],"sceneHook":"attest to","sceneHookZh":"证实证明","collocations":["attest to","witness attest","attest validity"],"examples":[{"en":"Multiple independent witnesses attest to the historical accuracy of reports.","zh":"多位独立证人证实了报告的历史准确性。","source":"ClawWords Editorial","mt":true},{"en":"Bronze and Iron Ages, as attested by its depictions on jewellery and other metal objects.","zh":"青铜时代和铁器时代，正如其在珠宝和其他金属物品上的描绘所证实的那样。","source":"IELTS","mt":true}],"color":"#2980B9","level":"C1","zipf":3.12,"lists":["green"]},
  {"id":"intern","word":"intern","ipa":"/ˈɪntɜːrn/","senses":[{"pos":"n.","zh":"实习生"},{"pos":"v.","zh":"拘留；扣押"}],"sceneHook":"medical intern","sceneHookZh":"实习医生","collocations":["medical intern","summer intern","intern at firm"],"examples":[{"en":"The dedicated medical intern worked long shifts at the hospital.","zh":"敬业的实习医生在医院轮班工作了很长时间。","source":"ClawWords Editorial","mt":true},{"en":"Every medical intern is assigned an experienced clinical supervisor to oversee diagnostic patient consultations.","zh":"每位实习医生都分配有一名经验丰富的临床导师来监督诊断接诊过程。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":3.6,"lists":["green"]},
  {"id":"repaint","word":"repaint","ipa":"/ˌriːˈpeɪnt/","senses":[{"pos":"v.","zh":"重新油漆；重画"}],"sceneHook":"repaint wall","sceneHookZh":"重新刷墙","collocations":["repaint wall","repaint the house","repaint furniture"],"examples":[{"en":"Workers began to repaint wall surfaces before hanging new exhibition artwork.","zh":"工人们在悬挂新展览艺术品之前开始重新粉刷墙面。","source":"ClawWords Editorial","mt":true},{"en":"The first thing people will see when they go in is that the foyer has been repainted in the original green and gold.","zh":"人们走进去首先会看到的是，门厅已经被重新粉刷成了原先的绿色和金色。","source":"IELTS","mt":true}],"color":"#D35400","level":"B1","zipf":2.85,"lists":["green"]},
  {"id":"censor","word":"censor","ipa":"/ˈsɛnsər/","senses":[{"pos":"v.","zh":"审查；删减"},{"pos":"n.","zh":"审查员"}],"sceneHook":"censor books","sceneHookZh":"审查书籍","collocations":["censor books","strictly censor","government censor"],"examples":[{"en":"Authoritarian regimes often attempt to censor books containing alternative viewpoints.","zh":"威权政权往往企图审查包含不同观点的书籍。","source":"ClawWords Editorial","mt":true},{"en":"Food and Drug Administration (FDA) offer considerable monitoring and notification functions, but these roles typically do not involve preemptive censoring.","zh":"美国食品药品监督管理局（FDA）提供了大量的监测和通报职能，但这些角色通常不涉及先发制人的审查。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.42,"lists":["green"]},
  {"id":"alight","word":"alight","ipa":"/əˈlaɪt/","senses":[{"pos":"v.","zh":"偶然发现；下车；飞落"},{"pos":"adj.","zh":"燃烧着的"}],"sceneHook":"alight on","sceneHookZh":"偶然发现","collocations":["alight on","alight from bus","set alight"],"examples":[{"en":"Researchers hoped to alight on unexpected historical records during archival searches.","zh":"研究人员希望在档案检索中偶然发现意想不到的历史记录。","source":"ClawWords Editorial","mt":true},{"en":"Historians had alighted on one interesting factor around the mid-18th century that required explanation.","zh":"历史学家们在18世纪中叶左右偶然发现了一个需要解释的有趣因素。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C1","zipf":2.88,"lists":["green"]},
  {"id":"vacant","word":"vacant","ipa":"/ˈveɪkənt/","senses":[{"pos":"adj.","zh":"空着的；空缺的；茫然的"}],"sceneHook":"vacant seat","sceneHookZh":"空座位","collocations":["vacant seat","vacant post","vacant position"],"examples":[{"en":"The polite passenger found a vacant seat on the evening train.","zh":"礼貌的乘客在晚班火车上找到了一个空座位。","source":"ClawWords Editorial","mt":true},{"en":"I'm ringing about the job I understand you have vacant.","zh":"我打电话是想咨询我获悉的贵方空缺的那个职位。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B1","zipf":3.82,"lists":["green"]},
  {"id":"truant","word":"truant","ipa":"/ˈtruːənt/","senses":[{"pos":"n.","zh":"逃学学生；旷课者"},{"pos":"v.","zh":"逃学"}],"sceneHook":"play truant","sceneHookZh":"旷课逃学","collocations":["play truant","habitual truant","truant officer"],"examples":[{"en":"Rebellious teenagers sometimes play truant rather than attend morning science classes.","zh":"叛逆的青少年有时会逃学而不去上早晨的科学课。","source":"ClawWords Editorial","mt":true},{"en":"Educational administrators launched targeted welfare counseling programs to assist students who persistently play truant.","zh":"教育管理人员推出了针对性的福利咨询计划，以帮助经常逃学的学生。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"C1","zipf":2.75,"lists":["green"]},
  {"id":"psychiatric","word":"psychiatric","ipa":"/ˌsaɪkiˈætrɪk/","senses":[{"pos":"adj.","zh":"精神病学的；精神病治疗的"}],"sceneHook":"psychiatric clinic","sceneHookZh":"精神病诊所","collocations":["psychiatric clinic","psychiatric hospital","psychiatric disorder"],"examples":[{"en":"The community funded a new psychiatric clinic to assist local patients.","zh":"社区资助了一家新的精神病诊所来帮助当地患者。","source":"ClawWords Editorial","mt":true},{"en":"Modern hospitals incorporate comprehensive psychiatric care units to address acute mental health emergencies effectively.","zh":"现代医院纳入了综合精神病照护病房，以有效应对突发精神健康紧急情况。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.48,"lists":["green"]},
  {"id":"bolster","word":"bolster","ipa":"/ˈboʊlstər/","senses":[{"pos":"v.","zh":"增强；支持；巩固"},{"pos":"n.","zh":"长垫"}],"sceneHook":"bolster confidence","sceneHookZh":"增强信心","collocations":["bolster confidence","bolster the economy","bolster support"],"examples":[{"en":"Constructive feedback from mentors helped bolster confidence among young research interns.","zh":"来自导师的建设性反馈有助于增强年轻研究实习生的信心。","source":"ClawWords Editorial","mt":true},{"en":"Central banks implemented lower interest rates in an aggressive effort to bolster domestic economic growth.","zh":"中央银行实行了更低的利率，以大力提振国内经济增长。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B2","zipf":3.65,"lists":["green"]},
  {"id":"tangibly","word":"tangibly","ipa":"/ˈtændʒəbli/","senses":[{"pos":"adv.","zh":"有形地；显著地；可触知地"}],"sceneHook":"tangibly improve","sceneHookZh":"显著改善","collocations":["tangibly improve","tangibly benefit","tangibly demonstrate"],"examples":[{"en":"New recycling initiatives will tangibly improve environmental cleanliness across urban neighborhoods.","zh":"新的回收举措将显著改善城市社区的环境清洁。","source":"ClawWords Editorial","mt":true},{"en":"Public investments in transport infrastructure tangibly enhanced economic productivity throughout the developing metropolitan area.","zh":"公共交通基础设施投资切实提高了整个发展中大都市区的经济生产力。","source":"IELTS","mt":true}],"color":"#16A085","level":"C1","zipf":2.7,"lists":["green"]},
  {"id":"alluvial","word":"alluvial","ipa":"/əˈluːviəl/","senses":[{"pos":"adj.","zh":"冲积的；冲积土的"}],"sceneHook":"alluvial soil","sceneHookZh":"冲积土壤","collocations":["alluvial soil","alluvial deposit","alluvial plain"],"examples":[{"en":"Farmers cultivated wheat on fertile alluvial soil along the winding river.","zh":"农民在蜿蜒河流两岸肥沃的冲积土壤上种植小麦。","source":"ClawWords Editorial","mt":true},{"en":"Civilizations traditionally flourished in river valleys enriched by mineral-laden alluvial deposits during periodic seasonal flooding.","zh":"在周期性季节洪水中富含矿物质的冲积物滋养下，河流流域历来孕育了繁盛的文明。","source":"IELTS","mt":true}],"color":"#2980B9","level":"C2","zipf":2.58,"lists":["green"]},
  {"id":"radius","word":"radius","ipa":"/ˈreɪdiəs/","senses":[{"pos":"n.","zh":"半径；辐射范围"}],"sceneHook":"turning radius","sceneHookZh":"转弯半径","collocations":["turning radius","within radius","outer radius"],"examples":[{"en":"The compact delivery car has a small turning radius for streets.","zh":"这款紧凑型送货车转弯半径小，适于街道行驶。","source":"ClawWords Editorial","mt":true},{"en":"Urban planners surveyed all primary residential neighborhoods located within a five-mile radius of the university.","zh":"城市规划者调查了位于大学五英里半径范围内的所有主要居民社区。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":3.42,"lists":["green"]},
  {"id":"wean","word":"wean","ipa":"/wiːn/","senses":[{"pos":"v.","zh":"使断奶；戒除"}],"sceneHook":"wean off","sceneHookZh":"逐渐戒除","collocations":["wean off","wean infant","gradually wean"],"examples":[{"en":"Doctors advise patients to wean off powerful painkillers under medical supervision.","zh":"医生建议患者在医疗监督下逐渐戒除强效止痛药。","source":"ClawWords Editorial","mt":true},{"en":"It is not effective for all insomniacs, but many users have weaned themselves off sleeping tablets as a result of its application.","zh":"它并非对所有失眠症患者都有效，但许多使用者由于应用了该方法，已逐渐摆脱了安眠药。","source":"IELTS","mt":true}],"color":"#D35400","level":"C1","zipf":3.1,"lists":["green"]},
  {"id":"pulley","word":"pulley","ipa":"/ˈpʊli/","senses":[{"pos":"n.","zh":"滑轮；滑轮组"}],"sceneHook":"pulley system","sceneHookZh":"滑轮系统","collocations":["pulley system","simple pulley","hoist by pulley"],"examples":[{"en":"The builder set up a sturdy pulley system to lift blocks.","zh":"建筑工人搭建了一个坚固的滑轮系统来提升石块。","source":"ClawWords Editorial","mt":true},{"en":"The key was to use a pulley system that would magnity the applied force.","zh":"关键在于使用一个能放大施加力的滑轮系统。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.12,"lists":["green"]},
  {"id":"inlet","word":"inlet","ipa":"/ˈɪnlɛt/","senses":[{"pos":"n.","zh":"小水湾；水湾；入口"}],"sceneHook":"narrow inlet","sceneHookZh":"狭窄水湾","collocations":["narrow inlet","air inlet","rocky inlet"],"examples":[{"en":"Fishing boats anchored quietly inside the narrow inlet during high tide.","zh":"渔船在涨潮时静静地停泊在狭窄的水湾内。","source":"ClawWords Editorial","mt":true},{"en":"Marine biologists examined benthic organisms thriving within a secluded coastal inlet sheltered from ocean currents.","zh":"海洋生物学家检查了在远离洋流侵袭的隐蔽沿海水湾中繁衍生息的底栖生物。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C1","zipf":3.05,"lists":["green"]},
  {"id":"shrewd","word":"shrewd","ipa":"/ʃruːd/","senses":[{"pos":"adj.","zh":"精明的；敏锐的"}],"sceneHook":"shrewd businessman","sceneHookZh":"精明商人","collocations":["shrewd businessman","shrewd investment","shrewd observer"],"examples":[{"en":"The shrewd businessman negotiated favorable export terms with foreign supply partners.","zh":"这位精明的商人与外国供应伙伴谈判达成了有利的出口条款。","source":"ClawWords Editorial","mt":true},{"en":"Had Westrope conducted methodical investigations or examined extensive film records in a shrewd plan to outrun his rivals?","zh":"韦斯特罗普是否开展了有条不紊的调查，抑或查阅了大量影像记录，以此制定出超越对手的精明计划？","source":"IELTS","mt":true}],"color":"#D9822B","level":"C1","zipf":3.25,"lists":["green"]},
  {"id":"grope","word":"grope","ipa":"/ɡroʊp/","senses":[{"pos":"v.","zh":"摸索；搜寻"}],"sceneHook":"grope around","sceneHookZh":"四处摸索","collocations":["grope around","grope for words","grope in darkness"],"examples":[{"en":"He had to grope around in the darkness to find keys.","zh":"他不得不在黑暗中四处摸索找钥匙。","source":"ClawWords Editorial","mt":true},{"en":"When the power failed abruptly, factory workers had to grope along corridor walls toward the emergency exit.","zh":"停电突然发生时，工厂工人们不得不沿着走廊墙壁摸索走向紧急出口。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.2,"lists":["green"]},
  {"id":"distill","word":"distill","ipa":"/dɪˈstɪl/","senses":[{"pos":"v.","zh":"蒸馏；提炼；吸取精华"}],"sceneHook":"distill water","sceneHookZh":"蒸馏水","collocations":["distill water","distill essence","distill into"],"examples":[{"en":"Laboratory assistants heat saline solution to distill water for chemical experiments.","zh":"实验室助理加热盐水溶液以蒸馏用于化学实验的水。","source":"ClawWords Editorial","mt":true},{"en":"Port-Royal abbey near Versailles distilled the essence of language, and no one since has celebrated more eloquently the magnitude of its achievement.","zh":"凡尔赛附近的波特罗亚尔修道院提炼出了语言的精髓，此后无人能比它更雄辩地颂扬这一成就的伟大。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.12,"lists":["green"]},
  {"id":"dormancy","word":"dormancy","ipa":"/ˈdɔːrmənsi/","senses":[{"pos":"n.","zh":"休眠；静止状态"}],"sceneHook":"winter dormancy","sceneHookZh":"冬季休眠","collocations":["winter dormancy","seed dormancy","period of dormancy"],"examples":[{"en":"Deciduous trees enter winter dormancy to survive freezing northern continental winters.","zh":"落叶乔木进入冬季休眠以度过寒冷的北方大陆严冬。","source":"ClawWords Editorial","mt":true},{"en":"Botanists study how environmental temperature variations influence the duration of seed dormancy in desert ecosystems.","zh":"植物学家研究环境温度变化如何影响沙漠生态系统中种子的休眠期。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C1","zipf":2.65,"lists":["green"]},
  {"id":"subscription","word":"subscription","ipa":"/səbˈskrɪpʃn/","senses":[{"pos":"n.","zh":"订阅；订阅费；定期捐款"}],"sceneHook":"annual subscription","sceneHookZh":"年度订阅","collocations":["annual subscription","cancel subscription","subscription fee"],"examples":[{"en":"She renewed her annual subscription to the digital economics research database.","zh":"她续订了数字经济研究数据库的年度订阅。","source":"ClawWords Editorial","mt":true},{"en":"Academic libraries allocate substantial portions of their annual budgets toward online periodical subscriptions.","zh":"学术图书馆将其年度预算的相当大部分分配给在线期刊订阅。","source":"IELTS","mt":true}],"color":"#16A085","level":"B1","zipf":4.1,"lists":["green"]},
  {"id":"shutter","word":"shutter","ipa":"/ˈʃʌtər/","senses":[{"pos":"n.","zh":"百叶窗；快门"},{"pos":"v.","zh":"关上百叶窗；停止营业"}],"sceneHook":"camera shutter","sceneHookZh":"相机快门","collocations":["camera shutter","wooden shutter","shutter speed"],"examples":[{"en":"Press the camera shutter gently to capture the flying coastal bird.","zh":"轻按相机快门以抓拍那只飞翔的海岸飞鸟。","source":"ClawWords Editorial","mt":true},{"en":"Photographers adjust the camera shutter speed to prevent motion blur when recording wildlife migration patterns.","zh":"摄影师在记录野生动物迁徙规律时会调整相机快门速度以防止运动模糊。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.55,"lists":["green"]},
  {"id":"stuffy","word":"stuffy","ipa":"/ˈstʌfi/","senses":[{"pos":"adj.","zh":"闷热的；不通气的；古板的"}],"sceneHook":"stuffy room","sceneHookZh":"闷热房间","collocations":["stuffy room","stuffy atmosphere","stuffy nose"],"examples":[{"en":"Open the double windows because this stuffy room needs fresh air.","zh":"把双层窗户打开，因为这间闷热的房间需要新鲜空气。","source":"ClawWords Editorial","mt":true},{"en":"And we've installed air conditioning, so it won't get so hot and stuffy.","zh":"而且我们安装了空调，所以不会变得那么闷热了。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":3.25,"lists":["green"]},
  {"id":"excusable","word":"excusable","ipa":"/ɪkˈskjuːzəbl/","senses":[{"pos":"adj.","zh":"可原谅的；可宽恕的"}],"sceneHook":"excusable mistake","sceneHookZh":"可原谅的错误","collocations":["excusable mistake","readily excusable","excusable delay"],"examples":[{"en":"A small typing error was deemed an excusable mistake by tutors.","zh":"导师认为一个小的打字错误是可原谅的错误。","source":"ClawWords Editorial","mt":true},{"en":"Inexperienced junior clerks may commit excusable procedural errors during their first week of administrative duties.","zh":"经验不足的初级文员在履职第一周可能会犯下可以原谅的程序性错误。","source":"IELTS","mt":true}],"color":"#D35400","level":"C1","zipf":2.82,"lists":["green"]},
  {"id":"corrode","word":"corrode","ipa":"/kəˈroʊd/","senses":[{"pos":"v.","zh":"腐蚀；侵蚀；受腐蚀"}],"sceneHook":"corrode metal","sceneHookZh":"腐蚀金属","collocations":["corrode metal","corrode slowly","corrode pipes"],"examples":[{"en":"Salty sea breezes will rapidly corrode metal fixtures installed along beaches.","zh":"咸涩的海风会迅速腐蚀沿海滩安装的金属构件。","source":"ClawWords Editorial","mt":true},{"en":"Acid rain and airborne chemical emissions can gradually corrode ancient stone sculptures and metallic historical monuments.","zh":"酸雨和空气中的化学排放物会逐渐侵蚀古代石雕和金属历史纪念碑。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"C1","zipf":2.95,"lists":["green"]},
  {"id":"antidote","word":"antidote","ipa":"/ˈæntidoʊt/","senses":[{"pos":"n.","zh":"解毒剂；解毒药；对抗手段"}],"sceneHook":"effective antidote","sceneHookZh":"有效解毒剂","collocations":["effective antidote","universal antidote","antidote to poison"],"examples":[{"en":"Doctors quickly administered an effective antidote to the snake bite victim.","zh":"医生迅速给蛇咬伤受害者使用了有效的解毒剂。","source":"ClawWords Editorial","mt":true},{"en":"Psychologists emphasize that outdoor recreation serves as a natural antidote to chronic occupational exhaustion.","zh":"心理学家强调，户外休闲是缓解慢性职业疲劳的天然良方。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B2","zipf":3.32,"lists":["green"]},
  {"id":"suppression","word":"suppression","ipa":"/səˈprɛʃn/","senses":[{"pos":"n.","zh":"镇压；压制；抑制"}],"sceneHook":"fire suppression","sceneHookZh":"灭火抑制","collocations":["fire suppression","suppression of truth","immune suppression"],"examples":[{"en":"The industrial warehouse installed an automatic fire suppression system last month.","zh":"该工业仓库上个月安装了自动灭火系统。","source":"ClawWords Editorial","mt":true},{"en":"Sociologists analyzed the systemic suppression of civil liberties under authoritarian governance throughout the nineteenth century.","zh":"社会学家分析了十九世纪威权统治下对公民自由的系统性压制。","source":"IELTS","mt":true}],"color":"#D9822B","level":"C1","zipf":3.42,"lists":["green"]},
  {"id":"lens","word":"lens","ipa":"/lɛnz/","senses":[{"pos":"n.","zh":"透镜；镜头；晶状体"}],"sceneHook":"camera lens","sceneHookZh":"相机镜头","collocations":["camera lens","contact lens","clean the lens"],"examples":[{"en":"The photographer wiped dust off the delicate camera lens carefully.","zh":"摄影师仔细地擦掉了精密相机镜头上的灰尘。","source":"ClawWords Editorial","mt":true},{"en":"Astronomers developed specialized optical lenses to capture distant cosmological phenomena with unprecedented clarity.","zh":"天文学家研制出专门的光学透镜，以前所未有的清晰度捕捉遥远的宇宙现象。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B1","zipf":4.25,"lists":["green"]},
  {"id":"dislodge","word":"dislodge","ipa":"/dɪsˈlɑːdʒ/","senses":[{"pos":"v.","zh":"逐出；用力移开；击脱"}],"sceneHook":"dislodge rocks","sceneHookZh":"震落岩石","collocations":["dislodge rocks","dislodge dirt","dislodge enemy"],"examples":[{"en":"Heavy mountain rain threatened to dislodge rocks above the mountain highway.","zh":"山区暴雨有可能会震落公路山上方的岩石。","source":"ClawWords Editorial","mt":true},{"en":"The bear used a tree branch on multiple occasions to dislodge a piece of meat hung out of his reach.","zh":"这只熊多次使用树枝弄下挂在它够不着地方的一块肉。","source":"IELTS","mt":true}],"color":"#22A06B","level":"C1","zipf":2.98,"lists":["green"]},
  {"id":"turret","word":"turret","ipa":"/ˈtɜːrɪt/","senses":[{"pos":"n.","zh":"角楼；小塔；炮塔"}],"sceneHook":"castle turret","sceneHookZh":"城堡角楼","collocations":["castle turret","gun turret","stone turret"],"examples":[{"en":"Guards stood watch high atop the ancient castle turret all night.","zh":"守卫在古老城堡角楼顶上通宵站岗。","source":"ClawWords Editorial","mt":true},{"en":"Imagining fairy-tale turrets and fire-breathing dragons, wicked witches and gallant heroes, she's creating an enchanting world.","zh":"想象着童话般的角楼、喷火的巨龙、邪恶的巫婆与英勇的英雄，她正在创造一个迷人的世界。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C1","zipf":3.12,"lists":["green"]},
  {"id":"naked","word":"naked","ipa":"/ˈneɪkɪd/","senses":[{"pos":"adj.","zh":"裸露的；无遮蔽的；裸体的"}],"sceneHook":"naked eye","sceneHookZh":"肉眼","collocations":["naked eye","naked truth","naked flame"],"examples":[{"en":"The bright comet was clearly visible to the naked eye tonight.","zh":"今晚凭肉眼就能清晰地看到那颗明亮的彗星。","source":"ClawWords Editorial","mt":true},{"en":"Naked mole rats can live for almost years and stay fit for nearly their entire lives.","zh":"裸鼹鼠几乎能存活数十年，并且几乎一生都能保持健康。","source":"IELTS","mt":true}],"color":"#16A085","level":"B1","zipf":4.15,"lists":["green"]},
  {"id":"probation","word":"probation","ipa":"/proʊˈbeɪʃn/","senses":[{"pos":"n.","zh":"缓刑；试用期"}],"sceneHook":"on probation","sceneHookZh":"缓刑试用","collocations":["on probation","period of probation","probation officer"],"examples":[{"en":"The court placed the young offender on probation for one year.","zh":"法院对该年轻违法者处以一年的缓刑。","source":"ClawWords Editorial","mt":true},{"en":"New administrative employees usually undergo a three-month probation period to assess professional competencies and team collaboration.","zh":"新入职的行政员工通常要经历为期三个月的试用期，以评估其专业能力和团队协作表现。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.45,"lists":["green"]},
  {"id":"warrant","word":"warrant","ipa":"/ˈwɔːrənt/","senses":[{"pos":"v.","zh":"使有必要；保证"},{"pos":"n.","zh":"搜查令；授权令"}],"sceneHook":"search warrant","sceneHookZh":"搜查令","collocations":["search warrant","arrest warrant","warrant attention"],"examples":[{"en":"Police officers presented a valid search warrant to enter the property.","zh":"警官出示了有效的搜查令以进入该处所。","source":"ClawWords Editorial","mt":true},{"en":"But these birds likely had mercury levels high enough to warrant concern for human consumption.","zh":"但这些鸟类体内的汞含量可能高到足以引起对其供人类食用的担忧。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":3.65,"lists":["green"]},
  {"id":"overdue","word":"overdue","ipa":"/ˌoʊvərˈduː/","senses":[{"pos":"adj.","zh":"逾期的；迟到的；早该发生的"}],"sceneHook":"long overdue","sceneHookZh":"早就该来","collocations":["long overdue","overdue books","overdue payment"],"examples":[{"en":"Many citizens felt comprehensive railway reforms were long overdue in regions.","zh":"许多市民感到各地区的全面铁路改革早就该来了。","source":"ClawWords Editorial","mt":true},{"en":"The municipal audit concluded that structural renovation of the primary water treatment plant was significantly overdue.","zh":"市政审计得出的结论是，主水处理厂的结构翻新工程已严重逾期。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":3.48,"lists":["green"]},
  {"id":"refresher","word":"refresher","ipa":"/rɪˈfrɛʃər/","senses":[{"pos":"n.","zh":"进修课程；补习；提醒物"}],"sceneHook":"refresher course","sceneHookZh":"进修课程","collocations":["refresher course","need a refresher","quick refresher"],"examples":[{"en":"Experienced medical nurses attended an intensive refresher course on cardiac care.","zh":"经验丰富的执业护士参加了有关心脏护理的强化进修课程。","source":"ClawWords Editorial","mt":true},{"en":"Qualified driving instructors must undertake a periodic refresher course to stay updated on transportation safety legislation.","zh":"合格的驾驶教练必须定期参加进修课程，以了解最新的交通安全法规。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":2.85,"lists":["green"]},
  {"id":"misjudge","word":"misjudge","ipa":"/ˌmɪsˈdʒʌdʒ/","senses":[{"pos":"v.","zh":"判断错误；估计不足"}],"sceneHook":"misjudge distance","sceneHookZh":"误判距离","collocations":["misjudge distance","misjudge the situation","misjudge character"],"examples":[{"en":"Inexperienced drivers often misjudge distance when parking in narrow city spots.","zh":"缺乏经验的驾驶员在狭窄的城市车位停车时往往会误判距离。","source":"ClawWords Editorial","mt":true},{"en":"Corporate executives who misjudge consumer demand often suffer substantial financial losses during competitive product launches.","zh":"误判消费者需求的企业高管在激烈的竞品发布期间往往会遭受重大财务损失。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B2","zipf":3.02,"lists":["green"]},
  {"id":"unyielding","word":"unyielding","ipa":"/ʌnˈjiːldɪŋ/","senses":[{"pos":"adj.","zh":"不屈服的；坚硬的；固执的"}],"sceneHook":"unyielding determination","sceneHookZh":"坚定的决心","collocations":["unyielding determination","unyielding rock","unyielding position"],"examples":[{"en":"The explorer showed unyielding determination while trekking across frozen tundra regions.","zh":"探险家在穿越冻原地区时展现出了坚定的决心。","source":"ClawWords Editorial","mt":true},{"en":"The labor union maintained an unyielding stance throughout protracted wage negotiations with corporate management.","zh":"在与企业管理层旷日持久的工资谈判中，工会始终保持着不屈服的立场。","source":"IELTS","mt":true}],"color":"#D9822B","level":"C2","zipf":2.65,"lists":["green"]},
  {"id":"vernacular","word":"vernacular","ipa":"/vərˈnækɪlər/","senses":[{"pos":"n.","zh":"白话；方言；本地话"},{"pos":"adj.","zh":"地方话的；本国的"}],"sceneHook":"local vernacular","sceneHookZh":"地方白话","collocations":["local vernacular","vernacular architecture","in the vernacular"],"examples":[{"en":"The novelist wrote vivid dialogue using the local vernacular of fishermen.","zh":"小说家使用渔民的地方白话创作了生动的对话。","source":"ClawWords Editorial","mt":true},{"en":"Medieval poets increasingly composed literary masterpieces in the Italian vernacular rather than formal classical Latin.","zh":"中世纪诗人越来越倾向于用意大利白话而非正规古典拉丁语创作文学杰作。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"C1","zipf":2.92,"lists":["green"]},
  {"id":"smuggle","word":"smuggle","ipa":"/ˈsmʌɡl/","senses":[{"pos":"v.","zh":"走私；私运；偷运"}],"sceneHook":"smuggle goods","sceneHookZh":"走私货物","collocations":["smuggle goods","smuggle across border","smuggle contraband"],"examples":[{"en":"Criminals tried to smuggle goods past the coastal security checkpoints.","zh":"罪犯企图将走私货物运过海岸安全检查站。","source":"ClawWords Editorial","mt":true},{"en":"Customs officers seized illegal wildlife products that criminal syndicates attempted to smuggle across international borders.","zh":"海关官员查获了犯罪集团企图偷运走私过境的非法野生动植物制品。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.42,"lists":["green"]},
  {"id":"gelatin","word":"gelatin","ipa":"/ˈdʒɛlətɪn/","senses":[{"pos":"n.","zh":"明胶；凝胶"}],"sceneHook":"unflavored gelatin","sceneHookZh":"无味明胶","collocations":["unflavored gelatin","gelatin capsules","powdered gelatin"],"examples":[{"en":"Dissolve a packet of unflavored gelatin into hot fruit juice.","zh":"将一包无味明胶溶解在热果汁中。","source":"ClawWords Editorial","mt":true},{"en":"Pharmaceutical companies widely utilize gelatin to manufacture biodegradable capsules that safely enclose pharmaceutical compounds.","zh":"制药公司广泛使用明胶来生产可生物降解的胶囊，以安全地包覆药物化合物。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B2","zipf":3.12,"lists":["green"]},
  {"id":"rumour","word":"rumour","ipa":"/ˈruːmər/","senses":[{"pos":"n.","zh":"传言；谣传"},{"pos":"v.","zh":"谣传"}],"sceneHook":"spread rumour","sceneHookZh":"散播谣言","collocations":["spread rumour","deny rumour","false rumour"],"examples":[{"en":"Careless workers should not spread rumour about upcoming company layoffs carelessly.","zh":"粗心的员工不应随意散播关于公司即将裁员的谣言。","source":"ClawWords Editorial","mt":true},{"en":"Productivity often suffers, as employees spend their time sharing rumours and providing one another with moral support rather than focusing on their jobs.","zh":"生产力往往会受到损害，因为员工把时间花在互相分享传言和提供精神支持上，而不是专注于本职工作。","source":"IELTS","mt":true}],"color":"#16A085","level":"B1","zipf":3.82,"lists":["green"]},
  {"id":"avail","word":"avail","ipa":"/əˈveɪl/","senses":[{"pos":"v.","zh":"利用；有助于"},{"pos":"n.","zh":"效用；利益"}],"sceneHook":"to no avail","sceneHookZh":"毫无效果","collocations":["to no avail","avail oneself of","of little avail"],"examples":[{"en":"The rescuers shouted loudly into the gorge to no avail whatsoever.","zh":"救援人员对着峡谷大声呼喊，却没有产生任何效果。","source":"ClawWords Editorial","mt":true},{"en":"Scientists tested several experimental compounds against the virulent pathogen, but unfortunately to no avail.","zh":"科学家针对这种剧毒病原体测试了几种实验性化合物，但遗憾的是毫无成效。","source":"IELTS","mt":true}],"color":"#2980B9","level":"C1","zipf":3.35,"lists":["green"]},
  {"id":"trimester","word":"trimester","ipa":"/traɪˈmɛstər/","senses":[{"pos":"n.","zh":"学期；孕期的三月期"}],"sceneHook":"first trimester","sceneHookZh":"第一学期","collocations":["first trimester","second trimester","academic trimester"],"examples":[{"en":"Medical examinations are critical during the first trimester of every pregnancy.","zh":"在每个怀孕周期的前三个月，医学检查都至关重要。","source":"ClawWords Editorial","mt":true},{"en":"Universities adopting a trimester academic calendar offer students greater flexibility to complete their degrees expeditiously.","zh":"采用三学期制的大学为学生提供了更大的灵活性，使他们能更快完成学位。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":3.25,"lists":["green"]},
  {"id":"reorient","word":"reorient","ipa":"/riˈɔːriɛnt/","senses":[{"pos":"v.","zh":"重新调整；重新定方位"}],"sceneHook":"reorient priorities","sceneHookZh":"调整优先项","collocations":["reorient priorities","reorient strategy","reorient focus"],"examples":[{"en":"The company sought to reorient priorities toward renewable clean energy development.","zh":"公司试图将优先事项重新调整为可再生清洁能源的发展。","source":"ClawWords Editorial","mt":true},{"en":"Educational reforms sought to reorient secondary school curricula toward developing practical technological capabilities.","zh":"教育改革力图重新调整中学课程，使其侧重于培养实用的技术能力。","source":"IELTS","mt":true}],"color":"#D35400","level":"C1","zipf":2.78,"lists":["green"]},
  {"id":"hinterland","word":"hinterland","ipa":"/ˈhɪntərlænd/","senses":[{"pos":"n.","zh":"内地；腹地；偏远地区"}],"sceneHook":"agricultural hinterland","sceneHookZh":"农业腹地","collocations":["agricultural hinterland","rural hinterland","coastal hinterland"],"examples":[{"en":"Supplies flowed continuously from the agricultural hinterland into the coastal metropolis.","zh":"物资不断地从农业腹地流向沿海大都市。","source":"ClawWords Editorial","mt":true},{"en":"The deepwater seaport expanded rapidly by transporting industrial manufactured exports manufactured across its vast economic hinterland.","zh":"该深水海港通过转运在其广阔经济腹地内生产的工业制成品出口而迅速扩张。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"C1","zipf":2.92,"lists":["green"]},
  {"id":"arrogance","word":"arrogance","ipa":"/ˈærəɡəns/","senses":[{"pos":"n.","zh":"傲慢；自大；狂妄"}],"sceneHook":"pure arrogance","sceneHookZh":"纯粹傲慢","collocations":["pure arrogance","intellectual arrogance","blind arrogance"],"examples":[{"en":"His dismissive tone revealed the pure arrogance behind his reckless decisions.","zh":"他不屑一顾的语气暴露出他鲁莽决定背后的纯粹傲慢。","source":"ClawWords Editorial","mt":true},{"en":"Diplomatic historians argue that excessive political arrogance frequently blinds national leadership to emergent geopolitical perils.","zh":"外交历史学家认为，过度的政治傲慢常常使国家领导层对新出现的地缘政治危险视而不见。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B2","zipf":3.48,"lists":["green"]},
  {"id":"apt","word":"apt","ipa":"/æpt/","senses":[{"pos":"adj.","zh":"恰当的；有倾向的"}],"sceneHook":"apt description","sceneHookZh":"贴切描述","collocations":["apt description","apt to happen","apt remark"],"examples":[{"en":"The reviewer offered an apt description of the complex novel plot.","zh":"书评人对小说复杂的情节给出了贴切的描述。","source":"ClawWords Editorial","mt":true},{"en":"So I decided to test whether various lines of motion were apt ways of showing move- ment or if they were merely idiosyncratic marks.","zh":"因此我决定测试各种运动线是否是展示运动的恰当方式，还是它们仅仅是特殊的标记。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B2","zipf":3.55,"lists":["green"]},
  {"id":"homogeneous","word":"homogeneous","ipa":"/ˌhoʊməˈdʒiːniəs/","senses":[{"pos":"adj.","zh":"同质的；同类的；均匀的"}],"sceneHook":"homogeneous mixture","sceneHookZh":"均匀混合物","collocations":["homogeneous mixture","homogeneous society","homogeneous population"],"examples":[{"en":"Stir the solvent until you form a homogeneous mixture without clumps.","zh":"搅拌溶剂，直到形成没有结块的均匀混合物。","source":"ClawWords Editorial","mt":true},{"en":"Anthropological surveys demonstrate that modern globalized cities are becoming culturally diverse rather than culturally homogeneous.","zh":"人类学调查表明，现代全球化城市正日益呈现文化多样性，而非文化上的同质化。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"C1","zipf":3.25,"lists":["green"]},
  {"id":"spasm","word":"spasm","ipa":"/ˈspæzəm/","senses":[{"pos":"n.","zh":"痉挛；抽搐；阵痛"}],"sceneHook":"muscle spasm","sceneHookZh":"肌肉痉挛","collocations":["muscle spasm","sudden spasm","spasm of pain"],"examples":[{"en":"The injured runner felt a sudden muscle spasm during the race.","zh":"受伤的赛跑者在比赛中感到肌肉突然痉挛。","source":"ClawWords Editorial","mt":true},{"en":"Athletes suffering from chronic dehydration frequently experience sudden involuntary muscular spasms during strenuous training sessions.","zh":"患有慢性脱水的运动员在艰苦训练期间经常会经历突发性的非自主肌肉痉挛。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.12,"lists":["green"]},
  {"id":"hunch","word":"hunch","ipa":"/hʌntʃ/","senses":[{"pos":"v.","zh":"耸肩；弓背"},{"pos":"n.","zh":"直觉；预感"}],"sceneHook":"hunch over","sceneHookZh":"弓背伏于","collocations":["hunch over","have a hunch","hunch shoulders"],"examples":[{"en":"Students should not hunch over screens for hours without taking breaks.","zh":"学生们不应该不休息就弓背伏在屏幕前好几个小时。","source":"ClawWords Editorial","mt":true},{"en":"Younger school-aged children read stories on smartphones; older kids don't read at all, but hunch over video games.","zh":"低龄学童在智能手机上阅读故事；大一点的孩子根本不阅读，而是弓着背沉迷于电子游戏。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B2","zipf":3.42,"lists":["green"]},
  {"id":"poll","word":"poll","ipa":"/poʊl/","senses":[{"pos":"n.","zh":"民意调查；投票"},{"pos":"v.","zh":"进行民意测验"}],"sceneHook":"opinion poll","sceneHookZh":"民意测验","collocations":["opinion poll","conduct a poll","go to the polls"],"examples":[{"en":"A recent opinion poll showed rising public support for educational reform.","zh":"最近的一项民意测验显示公众对教育改革的支持率上升。","source":"ClawWords Editorial","mt":true},{"en":"Political analysts frequently examine nationwide opinion polls to gauge shifting electoral preferences across diverse regional demographics.","zh":"政治分析师经常研究全国民意调查，以评估不同地区各人口群体的选民倾向偏好变化。","source":"IELTS","mt":true}],"color":"#16A085","level":"B1","zipf":4.15,"lists":["green"]},
  {"id":"homesick","word":"homesick","ipa":"/ˈhoʊmsɪk/","senses":[{"pos":"adj.","zh":"思乡的；想家的"}],"sceneHook":"feel homesick","sceneHookZh":"感到想家","collocations":["feel homesick","become homesick","homesick student"],"examples":[{"en":"First-year international students often feel homesick during the autumn semester.","zh":"一年级国际生在秋季学期常常感到想家。","source":"ClawWords Editorial","mt":true},{"en":"University counseling services provide peer mentoring to help newly arrived overseas scholars who feel profoundly homesick.","zh":"大学辅导处提供同伴朋辈辅导，以帮助深感思乡的新到海外学者。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B1","zipf":3.32,"lists":["green"]},
  {"id":"orientate","word":"orientate","ipa":"/ˈɔːriənteɪt/","senses":[{"pos":"v.","zh":"确定方向；使适应"}],"sceneHook":"orientate oneself","sceneHookZh":"适应环境","collocations":["orientate oneself","orientate toward","carefully orientate"],"examples":[{"en":"New students need several days to orientate oneself in the laboratory.","zh":"新生需要几天时间来让自己适应实验室的环境。","source":"ClawWords Editorial","mt":true},{"en":"With schooling beginning earlier and becoming increasingly exam-orientated, play is likely to get even less of a look-in.","zh":"随着入学年龄的提前和考试导向的愈发严重，游戏活动可能更难有一席之地。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":2.95,"lists":["green"]},
  {"id":"bump","word":"bump","ipa":"/bʌmp/","senses":[{"pos":"v.","zh":"碰；撞"},{"pos":"n.","zh":"肿块；凸起"}],"sceneHook":"bump into","sceneHookZh":"偶然撞见","collocations":["bump into","speed bump","feel bumps"],"examples":[{"en":"I did not expect to bump into my former teacher downtown.","zh":"我没想到会在市区偶遇我以前的老师。","source":"ClawWords Editorial","mt":true},{"en":"When the label's smooth, the food is fresh and then when you can feel bumps on the label, that means the food's gone bad.","zh":"当标签光滑时食物是新鲜的，而当你摸到标签上的凸起时，就意味着食物变质了。","source":"IELTS","mt":true}],"color":"#D35400","level":"B1","zipf":4.1,"lists":["green"]},
  {"id":"homestay","word":"homestay","ipa":"/ˈhoʊmsteɪ/","senses":[{"pos":"n.","zh":"寄宿家庭生活；寄宿家庭"}],"sceneHook":"arranged homestay","sceneHookZh":"寄宿家庭","collocations":["arranged homestay","homestay experience","live in homestay"],"examples":[{"en":"Living with an arranged homestay helped the student learn authentic English.","zh":"住在安排好的寄宿家庭帮助该学生学习了地道的英语。","source":"ClawWords Editorial","mt":true},{"en":"My friend is in homestay  and she really enjoys it  so I'd like to join a family as well.","zh":"我的朋友住在寄宿家庭，她非常喜欢，所以我也想加入一个家庭。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B1","zipf":3.2,"lists":["green"]},
  {"id":"acrobat","word":"acrobat","ipa":"/ˈækrəbæt/","senses":[{"pos":"n.","zh":"杂技演员；杂技艺人"}],"sceneHook":"skilled acrobat","sceneHookZh":"熟练杂技员","collocations":["skilled acrobat","circus acrobat","aerial acrobat"],"examples":[{"en":"A skilled acrobat balanced gracefully upon the high wire above spectators.","zh":"一名技艺熟练的杂技演员在观众上方的高空钢丝上优雅地保持平衡。","source":"ClawWords Editorial","mt":true},{"en":"Spectators applauded enthusiastically as the circus acrobat performed complex aerial somersaults without relying on safety ropes.","zh":"当杂技演员在不依赖安全绳的情况下表演复杂的空中后空翻时，观众热情鼓掌。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B2","zipf":2.85,"lists":["green"]},
  {"id":"irregularity","word":"irregularity","ipa":"/ɪˌrɛɡjəˈlærəti/","senses":[{"pos":"n.","zh":"不规则；违规行为；不整齐"}],"sceneHook":"financial irregularity","sceneHookZh":"财务违规","collocations":["financial irregularity","heart irregularity","surface irregularity"],"examples":[{"en":"Internal auditors uncovered serious financial irregularity within the procurement division.","zh":"内部审计人员揭露了采购部门内部严重的财务违规行为。","source":"ClawWords Editorial","mt":true},{"en":"Independent regulatory inspectors examined systemic accounting irregularities discovered during the annual corporate fiscal audit.","zh":"独立监管检查员审查了在企业年度财务审计中发现的系统性做账违规行为。","source":"IELTS","mt":true}],"color":"#D9822B","level":"C1","zipf":2.95,"lists":["green"]},
  {"id":"hive","word":"hive","ipa":"/haɪv/","senses":[{"pos":"n.","zh":"蜂巢；蜂箱；繁忙场所"}],"sceneHook":"busy hive","sceneHookZh":"繁忙蜂巢","collocations":["busy hive","bee hive","hive of activity"],"examples":[{"en":"During morning rush hour, the train station resembles a busy hive.","zh":"在早高峰期间，火车站就像一个繁忙的蜂巢。","source":"ClawWords Editorial","mt":true},{"en":"Researchers observed that worker bees return continuously to the communal hive to deposit gathered pollen nectar.","zh":"研究人员观察到工蜂不断返回群体蜂巢，以存放采集的花粉花蜜。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.4,"lists":["green"]},
  {"id":"plagiarism","word":"plagiarism","ipa":"/ˈpleɪdʒərɪzəm/","senses":[{"pos":"n.","zh":"抄袭；剽窃"}],"sceneHook":"commit plagiarism","sceneHookZh":"实施抄袭","collocations":["commit plagiarism","academic plagiarism","accused of plagiarism"],"examples":[{"en":"University rules strictly forbid students to commit plagiarism in essays.","zh":"大学校规严禁学生在论文中实施抄袭。","source":"ClawWords Editorial","mt":true},{"en":"Academic institutions enforce rigorous disciplinary penalties against students found guilty of intentional text plagiarism.","zh":"学术机构对被判定犯有故意文本抄袭行为的学生执行严厉的纪律处分。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.3,"lists":["green"]},
  {"id":"gallop","word":"gallop","ipa":"/ˈɡæləp/","senses":[{"pos":"v.","zh":"奔驰；飞驰"},{"pos":"n.","zh":"疾驰；飞奔"}],"sceneHook":"full gallop","sceneHookZh":"全速飞驰","collocations":["full gallop","canter and gallop","gallop away"],"examples":[{"en":"The wild horse raced at full gallop across the valley.","zh":"野马以全速飞驰穿越山谷。","source":"ClawWords Editorial","mt":true},{"en":"Mounted cavalry advanced at a vigorous gallop across the muddy battlefield during the nineteenth-century military encounter.","zh":"在十九世纪的军事交战中，骑兵部队在泥泞的战场上飞速疾驰前进。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B2","zipf":3.22,"lists":["green"]},
  {"id":"pledge","word":"pledge","ipa":"/plɛdʒ/","senses":[{"pos":"v.","zh":"发誓；保证；承诺"},{"pos":"n.","zh":"誓言；保证"}],"sceneHook":"pledge support","sceneHookZh":"承诺支持","collocations":["pledge support","pledge allegiance","solemn pledge"],"examples":[{"en":"Several donor nations agreed to pledge support for disaster relief efforts.","zh":"几个捐助国同意承诺为救灾工作提供支持。","source":"ClawWords Editorial","mt":true},{"en":"We are now seeing governments pledge support to national AI initiatives and compete in a technological race to dominate the burgeoning machine-learning sector.","zh":"我们现在看到各国政府承诺支持国家人工智能计划，并在主导蓬勃发展的机器学习领域的科技竞赛中展开竞争。","source":"IELTS","mt":true}],"color":"#16A085","level":"B2","zipf":3.7,"lists":["green"]},
  {"id":"stout","word":"stout","ipa":"/staʊt/","senses":[{"pos":"adj.","zh":"结实的；强壮的；肥胖的"},{"pos":"n.","zh":"黑啤酒"}],"sceneHook":"stout shoes","sceneHookZh":"结实的鞋","collocations":["stout shoes","stout fellow","stout resistance"],"examples":[{"en":"Hikers should always wear stout shoes when exploring rugged mountain trails.","zh":"徒步旅行者在探索崎岖山道时应始终穿着结实的鞋。","source":"ClawWords Editorial","mt":true},{"en":"The historic fortress resisted enemy artillery bombardment owing to its stout masonry walls and deep moat.","zh":"该历史堡垒由于其坚固的石砖墙体和深护城河，成功抵御了敌方的炮火轰击。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.28,"lists":["green"]},
  {"id":"greasy","word":"greasy","ipa":"/ˈɡriːsi/","senses":[{"pos":"adj.","zh":"油腻的；油污的；多油脂的"}],"sceneHook":"greasy food","sceneHookZh":"油腻食物","collocations":["greasy food","greasy hair","greasy hands"],"examples":[{"en":"Doctors recommend avoiding greasy food to maintain optimal cardiovascular health.","zh":"医生建议避免油腻食物以保持最佳心血管健康。","source":"ClawWords Editorial","mt":true},{"en":"It's very greasy Right  it does tend to get that way!","zh":"确实很油腻，没错，它往往就是会变成那样的！","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B1","zipf":3.65,"lists":["green"]},
  {"id":"compassionate","word":"compassionate","ipa":"/kəmˈpæʃənət/","senses":[{"pos":"adj.","zh":"有同情心的；慈悲的"}],"sceneHook":"compassionate care","sceneHookZh":"关怀照护","collocations":["compassionate care","compassionate leave","compassionate person"],"examples":[{"en":"Hospice nurses provide compassionate care to terminally ill elderly patients.","zh":"临终关怀护士为身患绝症的老年患者提供富有同情心的关怀照护。","source":"ClawWords Editorial","mt":true},{"en":"Medical schools increasingly incorporate ethical training to help future physicians communicate with compassionate empathy toward patients.","zh":"医学院越来越多地纳入伦理培训，以帮助未来的医生以富有同情心的同理心与患者沟通。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":3.42,"lists":["green"]},
  {"id":"casualty","word":"casualty","ipa":"/ˈkæʒuəlti/","senses":[{"pos":"n.","zh":"伤亡人员；伤亡；受害者"}],"sceneHook":"casualty care","sceneHookZh":"伤员护理","collocations":["casualty care","heavy casualty","casualty department"],"examples":[{"en":"Medical volunteers practiced casualty care protocols during emergency disaster drills.","zh":"医疗志愿者在紧急救灾演习中练习了伤员护理规程。","source":"ClawWords Editorial","mt":true},{"en":"I was glad I'd done a first aid course before I started, as that's a big help with the casualty care activities we do.","zh":"我很高兴在开始之前参加了急救课程，因为这对我们开展的伤员护理活动大有帮助。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.65,"lists":["green"]},
  {"id":"tug","word":"tug","ipa":"/tʌɡ/","senses":[{"pos":"v.","zh":"用力拉；使劲拖"},{"pos":"n.","zh":"用力拉；拖船"}],"sceneHook":"tug boat","sceneHookZh":"拖船引航","collocations":["tug boat","tug hard","tug at heart"],"examples":[{"en":"A powerful tug boat guided the cargo freighter safely into harbor.","zh":"一艘强力的拖船引导货轮安全进入港口。","source":"ClawWords Editorial","mt":true},{"en":"Harbor pilots dispatched an industrial tug boat to maneuver the colossal container vessel through treacherous navigation channels.","zh":"港口引航员派遣了一艘工业拖船，操纵庞大的集装箱货轮通过危险航道。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B2","zipf":3.45,"lists":["green"]},
  {"id":"spit","word":"spit","ipa":"/spɪt/","senses":[{"pos":"v.","zh":"吐出；唾弃"},{"pos":"n.","zh":"唾沫；唾液"}],"sceneHook":"spit out","sceneHookZh":"吐出数据","collocations":["spit out","spit on ground","spitting image"],"examples":[{"en":"The old printing machine will spit out pages if loaded properly.","zh":"如果正确装纸，这台老式打印机就会吐出纸张。","source":"ClawWords Editorial","mt":true},{"en":"At the end of each race, SWAN spits out data on each swimmer: Take a look, says Mason, pulling out a sheet of data.","zh":"在每场比赛结束时，SWAN系统都会吐出每个游泳选手的数据：“来看看吧，”梅森一边说，一边拿出一页数据。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B1","zipf":3.75,"lists":["green"]},
  {"id":"foremost","word":"foremost","ipa":"/ˈfɔːrmoʊst/","senses":[{"pos":"adj.","zh":"最重要的；首要的；最初的"}],"sceneHook":"foremost expert","sceneHookZh":"首要专家","collocations":["foremost expert","first and foremost","foremost authority"],"examples":[{"en":"She is recognized as the foremost expert in renewable solar technology.","zh":"她被公认为可再生太阳能技术领域最重要的专家。","source":"ClawWords Editorial","mt":true},{"en":"But language is foremost not just because it came first.","zh":"但语言之所以首要，不仅仅是因为它最早出现。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.65,"lists":["green"]},
  {"id":"notify","word":"notify","ipa":"/ˈnoʊtɪfaɪ/","senses":[{"pos":"v.","zh":"通知；通告；告知"}],"sceneHook":"promptly notify","sceneHookZh":"及时通知","collocations":["promptly notify","notify parents","notify authorities"],"examples":[{"en":"Schools will promptly notify parents if emergency campus closures become necessary.","zh":"如果需要紧急关闭校园，学校会及时通知家长。","source":"ClawWords Editorial","mt":true},{"en":"Aviation regulations obligate commercial airline carriers to notify passengers immediately regarding significant flight delays.","zh":"航空规章要求商业航空公司必须在发生重大航班延误时立即通知乘客。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B1","zipf":3.82,"lists":["green"]},
  {"id":"splendid","word":"splendid","ipa":"/ˈsplɛndɪd/","senses":[{"pos":"adj.","zh":"极好的；辉煌的；壮丽的"}],"sceneHook":"splendid view","sceneHookZh":"壮丽景色","collocations":["splendid view","splendid idea","splendid performance"],"examples":[{"en":"The mountain balcony offers a splendid view over the green valley.","zh":"山间阳台可将绿色山谷的壮丽景色尽收眼底。","source":"ClawWords Editorial","mt":true},{"en":"The restored Victorian opera house presented a splendid architectural backdrop for international cultural celebrations.","zh":"经过修缮的维多利亚时代歌剧院为国际文化庆典提供了壮丽的建筑背景。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B1","zipf":3.72,"lists":["green"]},
  {"id":"execute","word":"execute","ipa":"/ˈɛksɪkjuːt/","senses":[{"pos":"v.","zh":"执行；实施；处决"}],"sceneHook":"execute plan","sceneHookZh":"执行计划","collocations":["execute plan","execute command","execute project"],"examples":[{"en":"The project team must execute plan steps carefully to achieve success.","zh":"项目团队必须认真执行计划步骤以取得成功。","source":"ClawWords Editorial","mt":true},{"en":"Senior managers collaborated with departmental heads to execute corporate expansion strategies across emerging international markets.","zh":"高级管理层与部门负责人合作，在新兴国际市场上执行企业扩张战略。","source":"IELTS","mt":true}],"color":"#16A085","level":"B2","zipf":3.82,"lists":["green"]},
  {"id":"stereo","word":"stereo","ipa":"/ˈstɛrioʊ/","senses":[{"pos":"n.","zh":"立体声音响；立体声"},{"pos":"adj.","zh":"立体声的"}],"sceneHook":"stereo system","sceneHookZh":"立体声音响","collocations":["stereo system","stereo sound","in stereo"],"examples":[{"en":"He installed a modern stereo system inside his living room yesterday.","zh":"他昨天在起居室安装了现代化的立体声音响系统。","source":"ClawWords Editorial","mt":true},{"en":"Acoustic engineers evaluated the stereo sound reproduction capabilities of cutting-edge auditorium broadcasting equipment.","zh":"声学工程师评估了尖端礼堂广播设备的立体声重现能力。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B1","zipf":3.7,"lists":["green"]},
  {"id":"soak","word":"soak","ipa":"/soʊk/","senses":[{"pos":"v.","zh":"浸泡；湿透"},{"pos":"n.","zh":"浸泡"}],"sceneHook":"soak beans","sceneHookZh":"浸泡豆子","collocations":["soak beans","soak up","soak through"],"examples":[{"en":"Chefs soak beans overnight in cold water before preparing savory stew.","zh":"厨师在煮美味炖菜前，先把豆子在冷水中浸泡一夜。","source":"ClawWords Editorial","mt":true},{"en":"But, if tea is a factor in the combination lock, why didn't Japan forge ahead in a tea-soaked industrial revolution of its own?","zh":"但是，如果茶叶是密码锁中的一个要素，那么日本为什么没有在自己沉浸于茶香的工业革命中奋勇向前呢？","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B1","zipf":3.75,"lists":["green"]},
  {"id":"forgo","word":"forgo","ipa":"/fɔːrˈɡoʊ/","senses":[{"pos":"v.","zh":"放弃；弃绝"}],"sceneHook":"forgo dessert","sceneHookZh":"放弃甜点","collocations":["forgo dessert","forgo opportunity","forgo rights"],"examples":[{"en":"Health conscious diners often forgo dessert after eating a balanced meal.","zh":"注重健康的就餐者吃完均衡正餐后往往会放弃甜点。","source":"ClawWords Editorial","mt":true},{"en":"Undergraduate students occasionally forgo leisure pursuits to dedicate themselves entirely to competitive examination preparation.","zh":"本科生有时会放弃休闲娱乐，全身心投入到竞争激烈的备考中。","source":"IELTS","mt":true}],"color":"#D35400","level":"C1","zipf":3.12,"lists":["green"]},
  {"id":"siesta","word":"siesta","ipa":"/siˈɛstə/","senses":[{"pos":"n.","zh":"午睡；午休"}],"sceneHook":"afternoon siesta","sceneHookZh":"下午午睡","collocations":["afternoon siesta","take a siesta","daily siesta"],"examples":[{"en":"Workers in Mediterranean towns enjoy an afternoon siesta during hot summer.","zh":"地中海城镇的工人在炎热的夏天享受下午午睡。","source":"ClawWords Editorial","mt":true},{"en":"Sociologists observed that the cultural tradition of the afternoon siesta helps workers cope with extreme midday temperatures.","zh":"社会学家观察到，下午午睡的文化传统有助于工人们应对极端正午高温。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.02,"lists":["green"]},
  {"id":"stripe","word":"stripe","ipa":"/straɪp/","senses":[{"pos":"n.","zh":"条纹；斑纹"}],"sceneHook":"zebra stripe","sceneHookZh":"斑马条纹","collocations":["zebra stripe","white stripe","pin stripe"],"examples":[{"en":"The designer added a bold zebra stripe to the silk scarf.","zh":"设计师在丝巾上添加了一条醒目的斑马条纹。","source":"ClawWords Editorial","mt":true},{"en":"Evolutionary biologists investigate whether vertical coat stripes provide camouflage protection against predatory wildlife across savannah grasslands.","zh":"进化生物学家研究垂直皮毛条纹是否能在大草原上针对捕食性野生动物提供伪装保护。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B1","zipf":3.8,"lists":["green"]},
  {"id":"cosmic","word":"cosmic","ipa":"/ˈkɑːzmɪk/","senses":[{"pos":"adj.","zh":"宇宙的；庞大的"}],"sceneHook":"cosmic dust","sceneHookZh":"宇宙尘埃","collocations":["cosmic dust","cosmic ray","cosmic scale"],"examples":[{"en":"Telescopes detect glowing clouds of cosmic dust across distant outer galaxies.","zh":"望远镜在遥远的外星系中探测到发光的宇宙尘埃云。","source":"ClawWords Editorial","mt":true},{"en":"The AU is a cosmic measuring rod, and the basis of how we scale the Universe today.","zh":"天文单位是一根宇宙测量的标尺，也是我们今天衡量宇宙大小的基础。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B2","zipf":3.52,"lists":["green"]},
  {"id":"extendable","word":"extendable","ipa":"/ɪkˈstɛndəbl/","senses":[{"pos":"adj.","zh":"可延伸的；可延期的；可伸缩的"}],"sceneHook":"extendable table","sceneHookZh":"可伸缩桌","collocations":["extendable table","extendable ladder","extendable contract"],"examples":[{"en":"The dining room features a wooden extendable table for large dinner parties.","zh":"餐厅配有一张用于大型宴会的木制可伸缩桌子。","source":"ClawWords Editorial","mt":true},{"en":"Furniture manufacturers design compact extendable tables that optimize floor space in modern urban apartments.","zh":"家具制造商设计出紧凑的可伸缩桌子，以优化现代城市公寓的使用空间。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":2.65,"lists":["green"]},
  {"id":"jumble","word":"jumble","ipa":"/ˈdʒʌmbl/","senses":[{"pos":"n.","zh":"混乱；杂乱堆"},{"pos":"v.","zh":"使混乱；混杂"}],"sceneHook":"jumble of wires","sceneHookZh":"杂乱电线","collocations":["jumble of wires","jumble sale","in a jumble"],"examples":[{"en":"Behind the desk lay an untidy jumble of wires and adapters.","zh":"书桌后面堆放着杂乱缠绕的电线和适配器。","source":"ClawWords Editorial","mt":true},{"en":"Archaeologists sorting through excavated ruins uncovered a confused jumble of domestic pottery fragments and bronze ornaments.","zh":"考古学家在清理出土遗址时发现了一堆混乱杂乱的生活陶器碎片和青铜饰品。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.2,"lists":["green"]},
  {"id":"calibre","word":"calibre","ipa":"/ˈkælɪbər/","senses":[{"pos":"n.","zh":"才能；水准；口径"}],"sceneHook":"high calibre","sceneHookZh":"高水准","collocations":["high calibre","calibre of work","weapon calibre"],"examples":[{"en":"The university attracts researchers of exceptionally high calibre each academic semester.","zh":"该大学每个学期都吸引着极高水准的研究人员。","source":"ClawWords Editorial","mt":true},{"en":"Academic institutions strive to recruit international scholars of the highest professional calibre to bolster collaborative research output.","zh":"学术机构努力招募具备最高专业水准的国际学者，以提升合作研究成果。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C1","zipf":2.85,"lists":["green"]},
  {"id":"scrape","word":"scrape","ipa":"/skreɪp/","senses":[{"pos":"v.","zh":"刮掉；擦伤；刮出声"},{"pos":"n.","zh":"刮伤；擦痕"}],"sceneHook":"scrape ice","sceneHookZh":"刮除冰霜","collocations":["scrape ice","scrape through","scrape paint"],"examples":[{"en":"Drivers scrape ice off windshields before heading onto frosted morning highways.","zh":"司机在开上结霜的清晨公路前刮除挡风玻璃上的冰霜。","source":"ClawWords Editorial","mt":true},{"en":"Glaciologists analyze how advancing continental glaciers scrape bedrock surfaces, leaving striations indicative of directional flow.","zh":"冰川学家分析推进中的大陆冰川是如何刮磨基岩表面并留下指示流动方向的条痕的。","source":"IELTS","mt":true}],"color":"#16A085","level":"B1","zipf":3.65,"lists":["green"]},
  {"id":"spasmodic","word":"spasmodic","ipa":"/spæzˈmɑːdɪk/","senses":[{"pos":"adj.","zh":"阵发性的；间歇性的；痉挛的"}],"sceneHook":"spasmodic bursts","sceneHookZh":"阵发性爆发","collocations":["spasmodic bursts","spasmodic breathing","spasmodic effort"],"examples":[{"en":"The engine emitted sudden spasmodic bursts of steam along the tracks.","zh":"发动机沿铁轨突然阵发性地喷出蒸汽。","source":"ClawWords Editorial","mt":true},{"en":"Economic historians observed that technological innovation during that decade occurred in spasmodic bursts rather than continuous progression.","zh":"经济历史学家观察到，那十年的技术创新呈现阵发性爆发而非连续平稳进展。","source":"IELTS","mt":true}],"color":"#2980B9","level":"C2","zipf":2.4,"lists":["green"]},
  {"id":"extinguisher","word":"extinguisher","ipa":"/ɪkˈstɪŋɡwɪʃər/","senses":[{"pos":"n.","zh":"灭火器"}],"sceneHook":"fire extinguisher","sceneHookZh":"灭火器","collocations":["fire extinguisher","foam extinguisher","operate extinguisher"],"examples":[{"en":"Mount the red fire extinguisher beside the chemistry laboratory escape door.","zh":"将红色灭火器安装在化学实验室安全门旁。","source":"ClawWords Editorial","mt":true},{"en":"Occupational safety standards require commercial establishments to inspect portable fire extinguishers annually to verify functional readiness.","zh":"职业安全标准要求商业机构每年检查便携式灭火器，以核实其可用状态。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B1","zipf":3.25,"lists":["green"]},
  {"id":"assistantship","word":"assistantship","ipa":"/əˈsɪstəntʃɪp/","senses":[{"pos":"n.","zh":"助理奖学金；助教职位"}],"sceneHook":"graduate assistantship","sceneHookZh":"研究生助学金","collocations":["graduate assistantship","teaching assistantship","research assistantship"],"examples":[{"en":"She won a teaching graduate assistantship to fund her graduate studies.","zh":"她获得了一份研究生教学助学金来资助其研究生学业。","source":"ClawWords Editorial","mt":true},{"en":"Prospective doctoral candidates frequently evaluate university stipend offers that include tuition waivers alongside a research assistantship.","zh":"潜在的博士候选人经常评估包含学费减免及研究助教奖学金的大学津贴方案。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":2.5,"lists":["green"]},
  {"id":"offset","word":"offset","ipa":"/ˈɔːfsɛt/","senses":[{"pos":"v.","zh":"抵消；弥补；补偿"}],"sceneHook":"offset costs","sceneHookZh":"抵消成本","collocations":["offset costs","carbon offset","offset emissions"],"examples":[{"en":"Renewable energy rebates help homeowners offset costs of installing solar panels.","zh":"可再生能源补贴有助于房主抵消安装太阳能电池板的成本。","source":"ClawWords Editorial","mt":true},{"en":"Rats were found to be a major predator of kākāpō chicks and an insufficient number of chicks survived to offset adult mortality.","zh":"人们发现大鼠是鸮鹦鹉雏鸟的主要捕食者，幸存下来的雏鸟数量不足以弥补成年鸮鹦鹉的死亡率。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.55,"lists":["green"]},
  {"id":"detour","word":"detour","ipa":"/ˈdiːtʊr/","senses":[{"pos":"n.","zh":"绕道；迂回路由"},{"pos":"v.","zh":"绕路"}],"sceneHook":"make a detour","sceneHookZh":"绕道而行","collocations":["make a detour","take a detour","traffic detour"],"examples":[{"en":"Drivers had to make a detour because of the road repairs.","zh":"由于道路维修，驾驶员不得不绕道而行。","source":"ClawWords Editorial","mt":true},{"en":"BCE, Athenian ambassadors made a detour from their official travel to capture a ship sailing from Egypt, taking the wealth found onboard for themselves!","zh":"公元前，雅典使节在官方行程中绕道截获了一艘从埃及启航的船只，并将船上的财宝据为己有！","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B2","zipf":3.35,"lists":["green"]},
  {"id":"dividend","word":"dividend","ipa":"/ˈdɪvɪdɛnd/","senses":[{"pos":"n.","zh":"红利；股息；回报"}],"sceneHook":"annual dividend","sceneHookZh":"年度股息","collocations":["annual dividend","pay a dividend","dividend yield"],"examples":[{"en":"Shareholders received a healthy annual dividend following the profitable financial quarter.","zh":"在盈利的财政季度之后，股东们收到了可观的年度股息。","source":"ClawWords Editorial","mt":true},{"en":"Corporations that consistently distribute cash dividends often attract conservative institutional investors seeking dependable portfolio returns.","zh":"持续分配现金股息的公司往往能吸引寻求可靠投资组合回报的保守型机构投资者。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B2","zipf":3.65,"lists":["green"]},
  {"id":"marvellous","word":"marvellous","ipa":"/ˈmɑːrvələs/","senses":[{"pos":"adj.","zh":"绝佳的；极好的；令人惊叹的"}],"sceneHook":"marvellous opportunity","sceneHookZh":"绝佳机会","collocations":["marvellous opportunity","marvellous weather","marvellous achievement"],"examples":[{"en":"Studying abroad offers students a marvellous opportunity to broaden personal horizons.","zh":"出国留学为学生提供了开阔个人视野的绝佳机会。","source":"ClawWords Editorial","mt":true},{"en":"I don't think I've really said enough about the marvellous area you'll be walking in.","zh":"我觉得我对你们即将漫步的这个绝佳区域介绍得还不够多。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B1","zipf":3.65,"lists":["green"]},
  {"id":"sanitary","word":"sanitary","ipa":"/ˈsænətɛri/","senses":[{"pos":"adj.","zh":"卫生的；清洁的"}],"sceneHook":"sanitary conditions","sceneHookZh":"卫生条件","collocations":["sanitary conditions","sanitary landfill","sanitary napkins"],"examples":[{"en":"Inspectors confirmed that food processing factories maintained sanitary conditions throughout facilities.","zh":"检查员确认食品加工厂在整个设施中保持了卫生条件。","source":"ClawWords Editorial","mt":true},{"en":"Public health initiatives substantially reduced infectious disease transmission by improving community sanitary infrastructure in urban centers.","zh":"公共卫生倡议通过改善城市中心的社区卫生基础设施，大幅减少了传染病的传播。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.45,"lists":["green"]},
  {"id":"goggles","word":"goggles","ipa":"/ˈɡɑːɡlz/","senses":[{"pos":"n.","zh":"护目镜；风镜"}],"sceneHook":"safety goggles","sceneHookZh":"安全护目镜","collocations":["safety goggles","swimming goggles","protective goggles"],"examples":[{"en":"Always wear clear safety goggles before mixing concentrated chemical solutions together.","zh":"在将浓化学溶液混合在一起之前，请务必戴上清晰的安全护目镜。","source":"ClawWords Editorial","mt":true},{"en":"Anything from goggles to full bodysuits to workers who need it free of charge.","zh":"从护目镜到连体工作服，向有需要的工人免费提供任何物品。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B1","zipf":3.52,"lists":["green"]},
  {"id":"bronchitis","word":"bronchitis","ipa":"/brɑːŋˈkaɪtɪs/","senses":[{"pos":"n.","zh":"支气管炎"}],"sceneHook":"chronic bronchitis","sceneHookZh":"慢性支气管炎","collocations":["chronic bronchitis","acute bronchitis","treat bronchitis"],"examples":[{"en":"Patients diagnosed with chronic bronchitis experience persistent coughing throughout cold seasons.","zh":"被诊断患有慢性支气管炎的患者在寒冷季节会持续咳嗽。","source":"ClawWords Editorial","mt":true},{"en":"An increase in some cancers and bronchitis may reflect changing smoking habits and poorer air quality, say the researchers.","zh":"研究人员表示，某些癌症和支气管炎的增加可能反映了吸烟习惯的改变以及空气质量的恶化。","source":"IELTS","mt":true}],"color":"#16A085","level":"B2","zipf":3.12,"lists":["green"]},
  {"id":"intrusion","word":"intrusion","ipa":"/ɪnˈtruːʒn/","senses":[{"pos":"n.","zh":"侵扰；侵犯；闯入"}],"sceneHook":"unwanted intrusion","sceneHookZh":"不必要侵扰","collocations":["unwanted intrusion","intrusion into privacy","magma intrusion"],"examples":[{"en":"Celebrities complained that paparazzi photography constituted an unwanted intrusion into personal lives.","zh":"名人抱怨狗仔队的摄影构成了对个人生活不必要的侵扰。","source":"ClawWords Editorial","mt":true},{"en":"Legal scholars emphasize that warrantless electronic surveillance constitutes an impermissible intrusion into individual privacy rights.","zh":"法学学者强调，无搜查令的电子监控构成了对个人隐私权不可接受的侵犯。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.38,"lists":["green"]},
  {"id":"deviate","word":"deviate","ipa":"/ˈdiːvieɪt/","senses":[{"pos":"v.","zh":"偏离；越轨"},{"pos":"n.","zh":"偏离常规的人"}],"sceneHook":"deviate from","sceneHookZh":"偏离规范","collocations":["deviate from","deviate significantly","deviate slightly"],"examples":[{"en":"Aircraft navigators should never deviate from approved flight path coordinates.","zh":"飞机领航员决不能偏离核准的飞行路线坐标。","source":"ClawWords Editorial","mt":true},{"en":"Laboratory researchers are instructed never to deviate from established experimental safety protocols during hazardous microbiological trials.","zh":"在进行危险的微生物试验时，实验室研究人员被要求切勿偏离既定的实验安全规程。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":3.25,"lists":["green"]},
  {"id":"shorthand","word":"shorthand","ipa":"/ˈʃɔːrthænd/","senses":[{"pos":"n.","zh":"速记；速记法；简写"}],"sceneHook":"write shorthand","sceneHookZh":"记录速记","collocations":["write shorthand","shorthand notation","in shorthand"],"examples":[{"en":"Court reporters learn to write shorthand swiftly during rapid spoken trials.","zh":"法庭书记员学会在快速口头审理中迅速记录速记。","source":"ClawWords Editorial","mt":true},{"en":"Journalists historically relied upon specialized shorthand systems to transcribe speech rapidly before portable audio recording devices became ubiquitous.","zh":"在便携式录音设备普及之前，记者历史上依赖专门的速记系统来快速转录演讲。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":3.25,"lists":["green"]},
  {"id":"aerobics","word":"aerobics","ipa":"/eˈroʊbɪks/","senses":[{"pos":"n.","zh":"有氧健身操；有氧运动"}],"sceneHook":"water aerobics","sceneHookZh":"水中有氧操","collocations":["water aerobics","step aerobics","do aerobics"],"examples":[{"en":"Seniors attend weekly water aerobics classes to improve heart and joints.","zh":"老年人每周参加水中有氧健身课以改善心脏和关节健康。","source":"ClawWords Editorial","mt":true},{"en":"Sports scientists demonstrated that participating regularly in group aerobics enhances cardiovascular fitness and alleviates psychological stress.","zh":"体育科学家证明，经常参加集体有氧操能增强心血管健康并缓解心理压力。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B1","zipf":3.2,"lists":["green"]},
  {"id":"slat","word":"slat","ipa":"/slæt/","senses":[{"pos":"n.","zh":"板条；狭板"}],"sceneHook":"wooden slat","sceneHookZh":"木制板条","collocations":["wooden slat","bed slat","window slat"],"examples":[{"en":"The carpenter replaced every damaged wooden slat beneath the antique bed.","zh":"木匠更换了古董床下每根受损的木板条。","source":"ClawWords Editorial","mt":true},{"en":"Venetian blinds utilize adjustable horizontal slats to regulate the quantity of natural sunlight penetrating corporate offices.","zh":"百叶窗利用可调节的水平板条来调节射入企业办公室的自然阳光量。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C1","zipf":2.85,"lists":["green"]},
  {"id":"cinematography","word":"cinematography","ipa":"/ˌsɪnəməˈtɑːɡrəfi/","senses":[{"pos":"n.","zh":"电影摄影技术；电影摄影艺术"}],"sceneHook":"brilliant cinematography","sceneHookZh":"精湛摄影艺术","collocations":["brilliant cinematography","director of cinematography","masterful cinematography"],"examples":[{"en":"Critics praised the film for its brilliant cinematography and stunning landscapes.","zh":"影评人称赞该电影精湛的摄影艺术和迷人的风景。","source":"ClawWords Editorial","mt":true},{"en":"Film students study innovative camera movement and lighting design that characterize modern digital cinematography.","zh":"电影专业学生研究代表现代数字电影摄影特色的创新镜头运用和灯光设计。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B2","zipf":3.1,"lists":["green"]},
  {"id":"conditioner","word":"conditioner","ipa":"/kənˈdɪʃənər/","senses":[{"pos":"n.","zh":"护发素；调节器；护肤霜"}],"sceneHook":"hair conditioner","sceneHookZh":"护发素","collocations":["hair conditioner","air conditioner","fabric conditioner"],"examples":[{"en":"Apply moisturizing hair conditioner after shampooing to keep hair smooth daily.","zh":"洗发后涂抹保湿护发素，以保持头发每天顺滑。","source":"ClawWords Editorial","mt":true},{"en":"Cosmetic laboratories formulate hair conditioners with natural plant extracts to restore moisture and repair damaged fibers.","zh":"化妆品实验室采用天然植物提取物配制护发素，以补充水分并修复受损发丝。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B1","zipf":3.65,"lists":["green"]},
  {"id":"scrap","word":"scrap","ipa":"/skræp/","senses":[{"pos":"n.","zh":"碎片；废料"},{"pos":"v.","zh":"废弃；取消"}],"sceneHook":"scrap metal","sceneHookZh":"废弃金属","collocations":["scrap metal","scrap of paper","scrap the project"],"examples":[{"en":"Workers recycle tons of scrap metal at the municipal sorting yard.","zh":"工人们在市政分拣场回收数吨废金属。","source":"ClawWords Editorial","mt":true},{"en":"The automotive corporation decided to scrap redundant manufacturing operations to reduce escalating operational liabilities.","zh":"汽车公司决定取消多余的制造业务，以减少不断攀升的运营负债。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.75,"lists":["green"]},
  {"id":"tropospheric","word":"tropospheric","ipa":"/ˌtroʊpəˈsfɪrɪk/","senses":[{"pos":"adj.","zh":"对流层的"}],"sceneHook":"tropospheric ozone","sceneHookZh":"对流层臭氧","collocations":["tropospheric ozone","tropospheric layer","tropospheric scatter"],"examples":[{"en":"Industrial emissions contribute significantly to harmful tropospheric ozone levels across cities.","zh":"工业排放显著导致了城市中对流层臭氧有害浓度的上升。","source":"ClawWords Editorial","mt":true},{"en":"Atmospheric scientists monitor fluctuations in tropospheric greenhouse gas concentrations using advanced satellite telemetry.","zh":"大气科学家利用先进的卫星遥测技术监测对流层温室气体浓度的波动。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C2","zipf":2.3,"lists":["green"]},
  {"id":"earthwork","word":"earthwork","ipa":"/ˈɜːrθwɜːrk/","senses":[{"pos":"n.","zh":"土方工程；土垒；土筑工事"}],"sceneHook":"ancient earthwork","sceneHookZh":"古代土垒","collocations":["ancient earthwork","massive earthwork","defensive earthwork"],"examples":[{"en":"Tourists visited an ancient earthwork constructed during the Bronze Age period.","zh":"游客们参观了一座建于青铜时代时期的古代土垒。","source":"ClawWords Editorial","mt":true},{"en":"Archaeologists mapped extensive prehistoric earthworks constructed across the chalk hills to defend tribal agricultural settlements.","zh":"考古学家绘制了修建在白垩丘陵上用于防御部落农业聚落的庞大史前土方工程地图。","source":"IELTS","mt":true}],"color":"#16A085","level":"C2","zipf":2.6,"lists":["green"]},
  {"id":"horrify","word":"horrify","ipa":"/ˈhɔːrɪfaɪ/","senses":[{"pos":"v.","zh":"使恐惧；使震惊"}],"sceneHook":"deeply horrify","sceneHookZh":"深感震惊","collocations":["deeply horrify","horrify spectators","horrify public"],"examples":[{"en":"Violent news headlines can deeply horrify young children watching evening broadcasts.","zh":"暴力新闻头条可能会让观看晚间播报的幼童深感恐惧。","source":"ClawWords Editorial","mt":true},{"en":"Reports detailing catastrophic environmental damage caused by offshore oil spills horrified international conservation scientists.","zh":"详细描述海上溢油造成的灾难性环境破坏的报告令国际保护科学家深感震惊。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.15,"lists":["green"]},
  {"id":"enquire","word":"enquire","ipa":"/ɪnˈkwaɪər/","senses":[{"pos":"v.","zh":"询问；打听；调查"}],"sceneHook":"enquire about","sceneHookZh":"询问打听","collocations":["enquire about","enquire within","enquire after"],"examples":[{"en":"Prospective tourists telephoned the hotel to enquire about available family suites.","zh":"潜在的游客致电酒店以询问是否有家庭套房。","source":"ClawWords Editorial","mt":true},{"en":"I wanted to enquire about hiring a room in the Village Hall, for the evening of September the first.","zh":"我想打听一下在9月1日晚上租用乡村礼堂一个房间的事宜。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":3.5,"lists":["green"]},
  {"id":"curative","word":"curative","ipa":"/ˈkjʊrətɪv/","senses":[{"pos":"adj.","zh":"有疗效的；治病的"},{"pos":"n.","zh":"药品；治疗药"}],"sceneHook":"curative powers","sceneHookZh":"疗效力量","collocations":["curative powers","curative properties","curative effect"],"examples":[{"en":"Local folklore claimed the mineral spring water possessed rare curative powers.","zh":"当地民间传说称这种矿泉水具有罕见的疗效力量。","source":"ClawWords Editorial","mt":true},{"en":"British archaeologists to speculate that it was considered a place of healing, perhaps because bluestones were thought to have curative powers.","zh":"英国考古学家推测它被认为是一处疗愈之所，或许是因为人们认为蓝砂石具有治愈的力量。","source":"IELTS","mt":true}],"color":"#D35400","level":"C1","zipf":2.7,"lists":["green"]},
  {"id":"moderation","word":"moderation","ipa":"/ˌmɑːdəˈreɪʃn/","senses":[{"pos":"n.","zh":"适度；中庸；节制"}],"sceneHook":"in moderation","sceneHookZh":"适度节制","collocations":["in moderation","exercise moderation","practise moderation"],"examples":[{"en":"Nutritionists advise that drinking coffee in moderation supports daily physical energy.","zh":"营养学家建议适度喝咖啡有助于维持日常身体活力。","source":"ClawWords Editorial","mt":true},{"en":"Now two curious students are wondering whether Shakespeare advocates living a life of moderation or one of passionate engagement.","zh":"现在两个好奇的学生想知道莎士比亚到底是主张过一种适度节制的生活，还是全情投入的生活。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.42,"lists":["green"]},
  {"id":"trinket","word":"trinket","ipa":"/ˈtrɪŋkɪt/","senses":[{"pos":"n.","zh":"小饰品；不值钱的小玩艺"}],"sceneHook":"cheap trinket","sceneHookZh":"廉价小饰物","collocations":["cheap trinket","silver trinket","collect trinkets"],"examples":[{"en":"Street vendors sold every cheap trinket to tourists along the sunny promenade.","zh":"街头小贩在阳光明媚的散步道上向游客出售各种廉价小饰物。","source":"ClawWords Editorial","mt":true},{"en":"Archaeological excavations at the marketplace revealed Roman bronze trinkets and carved bone beads trade items.","zh":"在集市遗址的考古发掘中出土了罗马时期的青铜小饰物和雕花骨珠贸易物品。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C1","zipf":2.95,"lists":["green"]},
  {"id":"backbone","word":"backbone","ipa":"/ˈbækboʊn/","senses":[{"pos":"n.","zh":"脊椎；支柱"}],"sceneHook":"stiff backbone","sceneHookZh":"僵硬的脊椎","collocations":["stiff backbone","economic backbone","fractured backbone"],"examples":[{"en":"He injured his stiff backbone during the heavy lifting.","zh":"他在搬重物时伤到了僵硬的脊椎。","source":"ClawWords Editorial","mt":true},{"en":"Small businesses form the financial backbone of many regional economies worldwide.","zh":"小型企业构成了全球许多区域经济的财政支柱。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.52,"lists":["green"]},
  {"id":"tramp","word":"tramp","ipa":"/træmp/","senses":[{"pos":"v.","zh":"重步走；流浪"},{"pos":"n.","zh":"流浪汉；重步声"}],"sceneHook":"tramp through mud","sceneHookZh":"泥中跋涉","collocations":["tramp through mud","weary tramp","tramp across fields"],"examples":[{"en":"The tired hikers tramp through mud to reach their camp.","zh":"疲惫的徒步者踩着泥泞走向营地。","source":"ClawWords Editorial","mt":true},{"en":"Researchers had to tramp through dense forests to locate the rare plant species.","zh":"研究人员不得不穿过茂密的森林以寻找珍稀植物物种。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C1","zipf":3.12,"lists":["green"]},
  {"id":"disapprove","word":"disapprove","ipa":"/ˌdɪsəˈpruːv/","senses":[{"pos":"v.","zh":"不赞成；反对"}],"sceneHook":"strongly disapprove","sceneHookZh":"强烈反对","collocations":["strongly disapprove","disapprove of plans","openly disapprove"],"examples":[{"en":"Most committee members strongly disapprove of the proposed budget cuts.","zh":"大多数委员会成员强烈反对拟议的预算削减。","source":"ClawWords Editorial","mt":true},{"en":"Many conservative educators disapprove of using unsupervised artificial intelligence tools in classroom assessments.","zh":"许多保守的教育工作者反对在课堂评估中使用无人监督的人工智能工具。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B2","zipf":3.65,"lists":["green"]},
  {"id":"audacious","word":"audacious","ipa":"/ɔːˈdeɪʃəs/","senses":[{"pos":"adj.","zh":"大胆的；鲁莽的"}],"sceneHook":"audacious plan","sceneHookZh":"大胆的计划","collocations":["audacious plan","audacious attempt","audacious venture"],"examples":[{"en":"The company announced an audacious plan to expand into Asia.","zh":"该公司宣布了一项进军亚洲的大胆计划。","source":"ClawWords Editorial","mt":true},{"en":"The explorer devised an audacious strategy to traverse the polar ice cap alone.","zh":"探险家制定了一项大胆的策略，独自穿越极地冰原。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"C1","zipf":2.85,"lists":["green"]},
  {"id":"congregate","word":"congregate","ipa":"/ˈkɑːŋɡrɪɡeɪt/","senses":[{"pos":"v.","zh":"聚集；集合"}],"sceneHook":"congregate in crowds","sceneHookZh":"成群聚集","collocations":["congregate in crowds","congregate outside","congregate peacefully"],"examples":[{"en":"Protesters congregate in crowds near the city hall every afternoon.","zh":"抗议者每天下午在市政厅附近成群聚集。","source":"ClawWords Editorial","mt":true},{"en":"Reindeer once congregated on these icy patches in the later summer months to escape biting insects, and from the late Stone Age, hunters followed.","zh":"驯鹿曾经在夏末聚集在这些冰斑上以避开叮咬人的昆虫，从晚石器时代开始，猎人们紧随其后。","source":"IELTS","mt":true}],"color":"#22A06B","level":"C1","zipf":3.1,"lists":["green"]},
  {"id":"ensue","word":"ensue","ipa":"/ɪnˈsuː/","senses":[{"pos":"v.","zh":"接着发生；接踵而来"}],"sceneHook":"confusion will ensue","sceneHookZh":"必然陷入混乱","collocations":["confusion will ensue","ensue from conflict","silence ensued"],"examples":[{"en":"If rules are unclear, confusion will ensue among the workers.","zh":"如果规则不明确，工人们之间必然陷入混乱。","source":"ClawWords Editorial","mt":true},{"en":"Thinking computers and household robots failed to materialise, and a backlash ensued.","zh":"能够思考的计算机和家用机器人未能实现，随后引起了强烈反弹。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C1","zipf":3.48,"lists":["green"]},
  {"id":"dwell","word":"dwell","ipa":"/dwel/","senses":[{"pos":"v.","zh":"居住；细想"}],"sceneHook":"dwell in caves","sceneHookZh":"居于洞穴","collocations":["dwell in caves","dwell on mistakes","dwell in harmony"],"examples":[{"en":"Ancient human ancestors used to dwell in caves for warmth.","zh":"古代人类祖先曾住在洞穴中取暖。","source":"ClawWords Editorial","mt":true},{"en":"Most researchers conclude that pterosaurs are descended from a small tree-dwelling reptile that spent its life jumping between branches.","zh":"多数研究人员得出结论，翼龙是由一种一生在树枝间跳跃的小型树栖爬行动物演化而来的。","source":"IELTS","mt":true}],"color":"#16A085","level":"B2","zipf":3.72,"lists":["green"]},
  {"id":"recipient","word":"recipient","ipa":"/rɪˈsɪpiənt/","senses":[{"pos":"n.","zh":"接受者；受领人"}],"sceneHook":"award recipient","sceneHookZh":"获奖者","collocations":["award recipient","recipient of funds","intended recipient"],"examples":[{"en":"The award recipient thanked her mentors during the formal ceremony.","zh":"获奖者在正式仪式上感谢了她的导师。","source":"ClawWords Editorial","mt":true},{"en":"Each grant recipient must submit a comprehensive expenditure report before additional funding is released.","zh":"每位受资助者必须在发放额外资金前提交全面的支出报告。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.82,"lists":["green"]},
  {"id":"memorandum","word":"memorandum","ipa":"/ˌmeməˈrændəm/","senses":[{"pos":"n.","zh":"备忘录；便笺"}],"sceneHook":"internal memorandum","sceneHookZh":"内部备忘录","collocations":["internal memorandum","memorandum of understanding","confidential memorandum"],"examples":[{"en":"The director circulated an internal memorandum regarding the new safety guidelines.","zh":"主管分发了一份关于新安全指南的内部备忘录。","source":"ClawWords Editorial","mt":true},{"en":"Both university representatives signed a formal memorandum establishing an academic exchange partnership.","zh":"两位大学代表签署了一份建立学术交流合作关系的正式备忘录。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"C1","zipf":3.05,"lists":["green"]},
  {"id":"standpoint","word":"standpoint","ipa":"/ˈstændpɔɪnt/","senses":[{"pos":"n.","zh":"立场；观点"}],"sceneHook":"critical standpoint","sceneHookZh":"批判立场","collocations":["critical standpoint","from the standpoint of","theoretical standpoint"],"examples":[{"en":"The researcher evaluated the proposal from a critical standpoint.","zh":"研究员从批判的立场评估了该提案。","source":"ClawWords Editorial","mt":true},{"en":"From an ecological standpoint, protecting wetlands is essential for preserving coastal biodiversity and water quality.","zh":"从生态学的角度来看，保护湿地对于维护沿海生物多样性和水质至关重要。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":3.56,"lists":["green"]},
  {"id":"clutch","word":"clutch","ipa":"/klʌtʃ/","senses":[{"pos":"v.","zh":"紧握；抓牢"},{"pos":"n.","zh":"离合器；控制"}],"sceneHook":"clutch tightly","sceneHookZh":"紧紧抓牢","collocations":["clutch tightly","clutch pedal","slip from clutch"],"examples":[{"en":"Frightened passengers clutch tightly to handrails as the boat rocks.","zh":"受惊的乘客在船身摇晃时紧紧抓住扶手。","source":"ClawWords Editorial","mt":true},{"en":"Kerala Agricultural University freed a 12-kilometre- long canal from the clutches of the weed Salvinia molesta, popularly called 'African Payal' in Kerala.","zh":"喀拉拉邦农业大学清理了一条12公里长的运河，使其摆脱了当地被称为“非洲莲”的恶性杂草的控制。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.8,"lists":["green"]},
  {"id":"invaluable","word":"invaluable","ipa":"/ɪnˈvæljuəbl/","senses":[{"pos":"adj.","zh":"极宝贵的；极有价值的"}],"sceneHook":"invaluable advice","sceneHookZh":"宝贵建议","collocations":["invaluable advice","invaluable resource","invaluable contribution"],"examples":[{"en":"Her mentor gave her invaluable advice before the interview.","zh":"她的导师在面试前给了她宝贵的建议。","source":"ClawWords Editorial","mt":true},{"en":"I know that many parents who work find this service invaluable.","zh":"我知道许多有工作的父母发现这项服务极其宝贵。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B2","zipf":3.75,"lists":["green"]},
  {"id":"crank","word":"crank","ipa":"/kræŋk/","senses":[{"pos":"n.","zh":"曲柄；古怪之人"},{"pos":"v.","zh":"转动曲柄"}],"sceneHook":"turn the crank","sceneHookZh":"转动曲柄","collocations":["turn the crank","hand crank","crank mechanism"],"examples":[{"en":"You must turn the crank clockwise to start this engine.","zh":"你必须顺时针转动曲柄来启动这台引擎。","source":"ClawWords Editorial","mt":true},{"en":"Early telegraph systems relied on a manual crank to generate electrical currents across telegraph lines.","zh":"早期的电报系统依赖手动曲柄沿电报线路产生电流。","source":"IELTS","mt":true}],"color":"#D9822B","level":"C1","zipf":3.25,"lists":["green"]},
  {"id":"insecure","word":"insecure","ipa":"/ˌɪnsɪˈkjʊr/","senses":[{"pos":"adj.","zh":"缺乏自信的；不安全的"}],"sceneHook":"feel insecure","sceneHookZh":"感到不安","collocations":["feel insecure","financially insecure","insecure attachment"],"examples":[{"en":"Young children often feel insecure when entering a new school.","zh":"年幼的孩子在进入新学校时往往感到不安。","source":"ClawWords Editorial","mt":true},{"en":"Workers on temporary contracts frequently suffer from insecure employment conditions and minimal benefits.","zh":"签订临时合同的工人经常面临不稳定的就业条件和极低的福利待遇。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.9,"lists":["green"]},
  {"id":"aggravate","word":"aggravate","ipa":"/ˈæɡrəveɪt/","senses":[{"pos":"v.","zh":"加重；激怒"}],"sceneHook":"aggravate the injury","sceneHookZh":"加重伤势","collocations":["aggravate the injury","aggravate symptoms","aggravate tensions"],"examples":[{"en":"Running marathon races may aggravate the injury in your knee.","zh":"跑马拉松可能会加重你膝盖的伤势。","source":"ClawWords Editorial","mt":true},{"en":"Severe air pollution can aggravate respiratory conditions among elderly residents in urban environments.","zh":"严重的空气污染会加重城市环境中老年居民的呼吸系统疾病。","source":"IELTS","mt":true}],"color":"#22A06B","level":"C1","zipf":3.28,"lists":["green"]},
  {"id":"deception","word":"deception","ipa":"/dɪˈsepʃn/","senses":[{"pos":"n.","zh":"欺骗；诡计"}],"sceneHook":"clever deception","sceneHookZh":"巧妙骗局","collocations":["clever deception","practice deception","visual deception"],"examples":[{"en":"The detective quickly uncovered the clever deception behind the scam.","zh":"侦探很快揭开了骗局背后的巧妙诡计。","source":"ClawWords Editorial","mt":true},{"en":"Psychological experiments demonstrated that subtle deception can alter participants' perceptions of fairness and justice.","zh":"心理学实验表明，微妙的欺骗会改变参与者对公平和正义的认知。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B2","zipf":3.65,"lists":["green"]},
  {"id":"sharpen","word":"sharpen","ipa":"/ˈʃɑːrpn/","senses":[{"pos":"v.","zh":"削尖；磨练"}],"sceneHook":"sharpen skills","sceneHookZh":"磨砺技能","collocations":["sharpen skills","sharpen knives","sharpen focus"],"examples":[{"en":"Daily practice will sharpen skills needed for high school mathematics.","zh":"日常练习将磨砺高中数学所需的技能。","source":"ClawWords Editorial","mt":true},{"en":"This book also serves readers who simply want to sharpen their analytical skills.","zh":"这本书也适合那些仅仅想要磨炼自身分析技能的读者。","source":"IELTS","mt":true}],"color":"#16A085","level":"B1","zipf":4.1,"lists":["green"]},
  {"id":"pliable","word":"pliable","ipa":"/ˈplaɪəbl/","senses":[{"pos":"adj.","zh":"易弯曲的；柔韧的"}],"sceneHook":"soft and pliable","sceneHookZh":"柔软柔韧","collocations":["soft and pliable","pliable plastic","pliable material"],"examples":[{"en":"Warm clay becomes soft and pliable under the sculptor's hands.","zh":"温热的黏土在雕塑家手中变得柔软而柔韧。","source":"ClawWords Editorial","mt":true},{"en":"These could be virtually unbreakable, lighter and much more pliable leading to planes that are 50 times lighter than at present.","zh":"这些材料几乎坚不可摧、更轻且柔韧得多，使得制造比目前轻50倍的飞机成为可能。","source":"IELTS","mt":true}],"color":"#2980B9","level":"C2","zipf":2.7,"lists":["green"]},
  {"id":"sophisticate","word":"sophisticate","ipa":"/səˈfɪstɪkeɪt/","senses":[{"pos":"n.","zh":"见多识广者"},{"pos":"v.","zh":"使精巧；弄复杂"}],"sceneHook":"urban sophisticate","sceneHookZh":"都市通达之人","collocations":["urban sophisticate","cosmopolitan sophisticate","cultural sophisticate"],"examples":[{"en":"She lived like an urban sophisticate in the capital city.","zh":"她在首都生活得像个见多识广的都市通达之人。","source":"ClawWords Editorial","mt":true},{"en":"As they began to settle, grow plonts and herd animals, the need for a sophisticated number system became paramount.","zh":"随着他们开始定居、种植作物和放牧动物，建立一套精密的数字系统的需求变得至关重要。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"C1","zipf":2.8,"lists":["green"]},
  {"id":"identifiable","word":"identifiable","ipa":"/aɪˌdentɪˈfaɪəbl/","senses":[{"pos":"adj.","zh":"可辨认的；可确认的"}],"sceneHook":"clearly identifiable","sceneHookZh":"清晰可辨","collocations":["clearly identifiable","easily identifiable","readily identifiable"],"examples":[{"en":"The landmark tower remained clearly identifiable even through thick mist.","zh":"即使透过浓雾，地标塔依然清晰可辨。","source":"ClawWords Editorial","mt":true},{"en":"Why are some of the engravings of animals very accurate as you'd expect - all clearly identifiable - and others quite unrealistic?","zh":"为什么有些动物石刻正如预期的那样非常精准且清晰可辨，而另一些却相当不切实际？","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":3.55,"lists":["green"]},
  {"id":"nominal","word":"nominal","ipa":"/ˈnɑːmɪnl/","senses":[{"pos":"adj.","zh":"名义上的；微不足道的"}],"sceneHook":"nominal fee","sceneHookZh":"象征性收费","collocations":["nominal fee","nominal value","nominal leader"],"examples":[{"en":"Visitors pay a nominal fee to enter the botanical gardens.","zh":"游客只需支付象征性的入园费用即可进入植物园。","source":"ClawWords Editorial","mt":true},{"en":"The organization charges a nominal fee to cover basic administrative costs for attending public lectures.","zh":"该组织收取微薄的费用以支付参加公开讲座的基本行政开销。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"C1","zipf":3.42,"lists":["green"]},
  {"id":"vet","word":"vet","ipa":"/vet/","senses":[{"pos":"n.","zh":"兽医"},{"pos":"v.","zh":"审查；诊治"}],"sceneHook":"visit the vet","sceneHookZh":"看兽医","collocations":["visit the vet","experienced vet","vet candidates"],"examples":[{"en":"We must visit the vet when our puppy feels sick.","zh":"小狗生病时我们必须去看兽医。","source":"ClawWords Editorial","mt":true},{"en":"The farmer wasn't too happy I asked my farmer how much he depended on the vet to deal with health problems.","zh":"农场主不太高兴；我问农场主他在解决健康问题方面有多依赖兽医。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B1","zipf":4.15,"lists":["green"]},
  {"id":"reinstate","word":"reinstate","ipa":"/ˌriːɪnˈsteɪt/","senses":[{"pos":"v.","zh":"使复职；恢复"}],"sceneHook":"reinstate the policy","sceneHookZh":"恢复这项政策","collocations":["reinstate the policy","reinstate an employee","reinstate service"],"examples":[{"en":"The university decided to reinstate the policy after strong student protest.","zh":"在强烈的学生抗议后，大学决定恢复这项政策。","source":"ClawWords Editorial","mt":true},{"en":"The board voted unanimously to reinstate the dismissed director following an independent workplace investigation.","zh":"在独立的工作场所调查后，董事会一致投票决定恢复被解雇的主管职务。","source":"IELTS","mt":true}],"color":"#D9822B","level":"C1","zipf":3.2,"lists":["green"]},
  {"id":"lexicographer","word":"lexicographer","ipa":"/ˌleksɪˈkɑːɡrəfər/","senses":[{"pos":"n.","zh":"词典编纂者"}],"sceneHook":"skilled lexicographer","sceneHookZh":"词典编纂者","collocations":["skilled lexicographer","dictionary lexicographer","notable lexicographer"],"examples":[{"en":"The skilled lexicographer documented new slang words in the dictionary.","zh":"这位熟练的词典编纂者在词典中记录了新的俚语词汇。","source":"ClawWords Editorial","mt":true},{"en":"Samuel Johnson spent almost a decade working diligently as a lexicographer to compile his famous dictionary.","zh":"塞缪尔·约翰逊作为词典编纂者勤奋工作了近十年，编写出了他著名的词典。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"C2","zipf":2.38,"lists":["green"]},
  {"id":"kneel","word":"kneel","ipa":"/niːl/","senses":[{"pos":"v.","zh":"跪下；下跪"}],"sceneHook":"kneel down","sceneHookZh":"跪下","collocations":["kneel down","kneel in prayer","kneel on the floor"],"examples":[{"en":"Gardening fans kneel down on pads while trimming flower beds.","zh":"园艺爱好者在修剪花坛时跪在软垫上。","source":"ClawWords Editorial","mt":true},{"en":"Devotees would regularly kneel before the ancient shrine to express reverence and seek spiritual blessings.","zh":"信徒们经常跪在古老的神龛前表达虔诚并祈求精神庇佑。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B1","zipf":4.02,"lists":["green"]},
  {"id":"feeble","word":"feeble","ipa":"/ˈfiːbl/","senses":[{"pos":"adj.","zh":"虚弱的；微弱的"}],"sceneHook":"feeble cry","sceneHookZh":"微弱的哭声","collocations":["feeble cry","feeble excuse","feeble attempt"],"examples":[{"en":"Rescuers heard a feeble cry beneath the heavy collapsed roof.","zh":"救援人员在沉重坍塌的屋顶下听到了微弱的哭声。","source":"ClawWords Editorial","mt":true},{"en":"Critics dismissed the minister's statement as a feeble defense against mounting allegations of administrative incompetence.","zh":"批评人士斥责部长的声明是对日益增多的行政无能指控的无力辩解。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B2","zipf":3.6,"lists":["green"]},
  {"id":"pulverise","word":"pulverise","ipa":"/ˈpʌlvəraɪz/","senses":[{"pos":"v.","zh":"粉碎；研磨成粉"}],"sceneHook":"pulverise into dust","sceneHookZh":"粉碎成灰尘","collocations":["pulverise into dust","pulverise rocks","pulverise grain"],"examples":[{"en":"Heavy machines pulverise into dust every piece of dry limestone.","zh":"重型机器将每一块干燥石灰石粉碎成灰尘。","source":"ClawWords Editorial","mt":true},{"en":"Industrial mills use rotating ceramic rollers to pulverise solid mineral ores into fine chemical powder.","zh":"工业磨机利用旋转的陶瓷滚轴将固体矿石研磨成精细的化学粉末。","source":"IELTS","mt":true}],"color":"#16A085","level":"C2","zipf":2.45,"lists":["green"]},
  {"id":"rot","word":"rot","ipa":"/rɑːt/","senses":[{"pos":"v.","zh":"腐烂；腐朽"},{"pos":"n.","zh":"腐烂；胡说"}],"sceneHook":"rot away","sceneHookZh":"腐烂掉","collocations":["rot away","begin to rot","wood rot"],"examples":[{"en":"Fallen autumn apples rot away quickly in the wet grass.","zh":"掉落的秋季苹果在湿草丛中很快腐烂掉。","source":"ClawWords Editorial","mt":true},{"en":"For example, production workers roted advancement very highly, whereas clerical workers rated advancement in the lower third of their list.","zh":"例如，生产工人将晋升排得非常高，而文职人员将晋升排在其清单的后三分之一。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.7,"lists":["green"]},
  {"id":"tome","word":"tome","ipa":"/toʊm/","senses":[{"pos":"n.","zh":"大部头著作；巨著"}],"sceneHook":"massive tome","sceneHookZh":"厚重巨著","collocations":["massive tome","scholarly tome","leather-bound tome"],"examples":[{"en":"The professor opened a massive tome on ancient European history.","zh":"教授打开了一本关于古代欧洲历史的厚重巨著。","source":"ClawWords Editorial","mt":true},{"en":"The library preserved a rare theological tome bound in medieval leather and filled with handwritten Latin annotations.","zh":"图书馆保存了一本装订在带有手写拉丁语批注的中世纪皮革里珍贵神学巨著。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"C2","zipf":2.65,"lists":["green"]},
  {"id":"interplay","word":"interplay","ipa":"/ˈɪntərpleɪ/","senses":[{"pos":"n.","zh":"相互影响；相互作用"}],"sceneHook":"complex interplay","sceneHookZh":"复杂相互作用","collocations":["complex interplay","dynamic interplay","interplay between factors"],"examples":[{"en":"Climate depends on the complex interplay between oceans and atmosphere.","zh":"气候取决于海洋与大气之间复杂的相互作用。","source":"ClawWords Editorial","mt":true},{"en":"The study analyzed the complex interplay between cultural heritage and economic development in urban tourism.","zh":"该研究分析了城市旅游中文化遗产与经济发展之间复杂的相互作用。","source":"IELTS","mt":true}],"color":"#D35400","level":"C1","zipf":3.25,"lists":["green"]},
  {"id":"vitality","word":"vitality","ipa":"/vaɪˈtæləti/","senses":[{"pos":"n.","zh":"生命力；活力"}],"sceneHook":"youthful vitality","sceneHookZh":"年轻活力","collocations":["youthful vitality","restore vitality","economic vitality"],"examples":[{"en":"Regular exercise helps older adults retain their youthful vitality longer.","zh":"经常锻炼有助于老年人更长久地保持年轻活力。","source":"ClawWords Editorial","mt":true},{"en":"When you see the Asiatic lion in India, what you sense is enormous vitality.","zh":"当你在印度看到亚洲狮时，你所感受到的是巨大的生命力。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.6,"lists":["green"]},
  {"id":"splint","word":"splint","ipa":"/splɪnt/","senses":[{"pos":"n.","zh":"夹板"},{"pos":"v.","zh":"用夹板固定"}],"sceneHook":"apply a splint","sceneHookZh":"固定夹板","collocations":["apply a splint","wooden splint","padded splint"],"examples":[{"en":"The paramedic had to apply a splint to the broken wrist.","zh":"护理人员不得不在骨折的手腕上固定夹板。","source":"ClawWords Editorial","mt":true},{"en":"First responders must properly splint fractured limbs before moving injured patients across rough mountain terrain.","zh":"急救人员在崎岖的山区地形转移受伤患者前，必须妥善用夹板固定骨折的肢体。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C1","zipf":2.95,"lists":["green"]},
  {"id":"prerequisite","word":"prerequisite","ipa":"/ˌpriːˈrekwəzɪt/","senses":[{"pos":"n.","zh":"先决条件；前提"},{"pos":"adj.","zh":"先决的"}],"sceneHook":"essential prerequisite","sceneHookZh":"必要先决条件","collocations":["essential prerequisite","course prerequisite","prerequisite for success"],"examples":[{"en":"Fluency in Spanish is an essential prerequisite for this posting.","zh":"流利的西班牙语是获得该职位的必要先决条件。","source":"ClawWords Editorial","mt":true},{"en":"Passing the preliminary examination remains a mandatory prerequisite before doctoral candidates can commence dissertation research.","zh":"通过初试仍然是博士候选人开始学位论文研究前必修的先决条件。","source":"IELTS","mt":true}],"color":"#D9822B","level":"C1","zipf":3.15,"lists":["green"]},
  {"id":"resonate","word":"resonate","ipa":"/ˈrezəneɪt/","senses":[{"pos":"v.","zh":"共鸣；产生回响"}],"sceneHook":"resonate deeply","sceneHookZh":"引起深刻共鸣","collocations":["resonate deeply","resonate with audiences","resonate through halls"],"examples":[{"en":"Her emotional stories resonate deeply with young college students everywhere.","zh":"她充满情感的故事引起了各地年轻大学生的深刻共鸣。","source":"ClawWords Editorial","mt":true},{"en":"The speaker's passionate arguments about environmental conservation continue to resonate strongly with contemporary youth movements.","zh":"演讲者关于环境保护的激情论述继续在当代青年运动中引起强烈共鸣。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.5,"lists":["green"]},
  {"id":"coupon","word":"coupon","ipa":"/ˈkuːpɑːn/","senses":[{"pos":"n.","zh":"优惠券；礼券"}],"sceneHook":"discount coupon","sceneHookZh":"折扣优惠券","collocations":["discount coupon","redeem a coupon","digital coupon"],"examples":[{"en":"She used a discount coupon to buy groceries this morning.","zh":"她今天早上用了一张折扣优惠券买杂货。","source":"ClawWords Editorial","mt":true},{"en":"Retail businesses distribute promotional coupons to attract new consumers and retain existing brand loyalty during recessions.","zh":"零售企业发放促销优惠券，以在经济衰退期间吸引新消费者并维持现有的品牌忠诚度。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B1","zipf":4.2,"lists":["green"]},
  {"id":"bachelor","word":"bachelor","ipa":"/ˈbætʃələr/","senses":[{"pos":"n.","zh":"单身汉；学士"}],"sceneHook":"bachelor degree","sceneHookZh":"学士学位","collocations":["bachelor degree","eligible bachelor","bachelor pad"],"examples":[{"en":"He completed his bachelor degree in chemical engineering last June.","zh":"他去年六月完成了化学工程学士学位。","source":"ClawWords Editorial","mt":true},{"en":"Applicants seeking professional engineering positions generally require at least an accredited bachelor degree in science.","zh":"寻求专业工程职位的申请人通常需要至少拥有经认证的理学学士学位。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B1","zipf":4.1,"lists":["green"]},
  {"id":"enlighten","word":"enlighten","ipa":"/ɪnˈlaɪtn/","senses":[{"pos":"v.","zh":"启发；开导"}],"sceneHook":"enlighten the public","sceneHookZh":"启发公众","collocations":["enlighten the public","enlighten students","enlighten readers"],"examples":[{"en":"Science lectures aim to enlighten the public on global warming.","zh":"科学讲座旨在就全球变暖启发公众。","source":"ClawWords Editorial","mt":true},{"en":"Philosophical writings during the eighteenth century served to enlighten European societies regarding democratic governance and human rights.","zh":"十八世纪的哲学著作在民主治理与人权方面启蒙了欧洲社会。","source":"IELTS","mt":true}],"color":"#16A085","level":"B2","zipf":3.35,"lists":["green"]},
  {"id":"hesitate","word":"hesitate","ipa":"/ˈhezɪteɪt/","senses":[{"pos":"v.","zh":"犹豫；迟疑"}],"sceneHook":"hesitate to ask","sceneHookZh":"犹豫不敢问","collocations":["hesitate to ask","hesitate before speaking","do not hesitate"],"examples":[{"en":"Please do not hesitate to ask if problems arise today.","zh":"今天如果出现问题，请不要犹豫随时提问。","source":"ClawWords Editorial","mt":true},{"en":"Prospective home buyers often hesitate when interest rates fluctuate unpredictably over short economic intervals.","zh":"当利率在短期经济周期内难以预测地波动时，潜在购房者往往会犹豫不决。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B1","zipf":4.25,"lists":["green"]},
  {"id":"accreditation","word":"accreditation","ipa":"/əˌkredɪˈteɪʃn/","senses":[{"pos":"n.","zh":"官方认证；鉴定合格"}],"sceneHook":"gain accreditation","sceneHookZh":"获得认证","collocations":["gain accreditation","hospital accreditation","academic accreditation"],"examples":[{"en":"The medical institute worked hard to gain accreditation this year.","zh":"该医学研究所今年努力争取获得认证。","source":"ClawWords Editorial","mt":true},{"en":"Colleges must undergo rigorous evaluations every five years to maintain their national institutional accreditation status.","zh":"高校必须每五年接受一次严格评估，以维持其国家机构的认证资格。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"C1","zipf":3.1,"lists":["green"]},
  {"id":"internist","word":"internist","ipa":"/ˈɪntɜːrnɪst/","senses":[{"pos":"n.","zh":"内科医生"}],"sceneHook":"consult an internist","sceneHookZh":"咨询内科医生","collocations":["consult an internist","certified internist","experienced internist"],"examples":[{"en":"Patients with chronic fatigue should consult an internist for evaluation.","zh":"患有慢性疲劳的患者应咨询内科医生进行评估。","source":"ClawWords Editorial","mt":true},{"en":"A qualified internist specializes in diagnosing complex adult illnesses involving multiple organ systems simultaneously.","zh":"一位合格的内科医生专门诊断涉及多个器官系统的复杂成年人疾病。","source":"IELTS","mt":true}],"color":"#D35400","level":"C2","zipf":2.55,"lists":["green"]},
  {"id":"stammer","word":"stammer","ipa":"/ˈstæmər/","senses":[{"pos":"v.","zh":"口吃；结结巴巴地说"},{"pos":"n.","zh":"口吃"}],"sceneHook":"nervous stammer","sceneHookZh":"紧张结巴","collocations":["nervous stammer","slight stammer","stammer an apology"],"examples":[{"en":"Nervous speakers often display a nervous stammer before large crowds.","zh":"紧张的演讲者在大批听众面前常常表现出紧张结巴。","source":"ClawWords Editorial","mt":true},{"en":"Speech therapists implement specialized breathing exercises to assist children who develop an involuntary speech stammer.","zh":"言语治疗师采用专门的呼吸练习来帮助出现非自愿言语口吃的儿童。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":3.3,"lists":["green"]},
  {"id":"fickle","word":"fickle","ipa":"/ˈfɪkl/","senses":[{"pos":"adj.","zh":"易变的；无常的"}],"sceneHook":"fickle weather","sceneHookZh":"多变天气","collocations":["fickle weather","fickle public","fickle fortune"],"examples":[{"en":"Spring in the northern valley brings notoriously fickle weather conditions.","zh":"北部山谷的春季带来了出了名变化无常的天气条件。","source":"ClawWords Editorial","mt":true},{"en":"Marketing executives frequently struggle to anticipate demand patterns influenced by fickle consumer preferences and trends.","zh":"营销主管经常难以预测受善变消费者偏好和潮流影响的需求模式。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C1","zipf":3.25,"lists":["green"]},
  {"id":"consecutive","word":"consecutive","ipa":"/kənˈsekjətɪv/","senses":[{"pos":"adj.","zh":"连续的；连贯的"}],"sceneHook":"consecutive days","sceneHookZh":"连续数日","collocations":["consecutive days","consecutive wins","consecutive quarters"],"examples":[{"en":"Torrential rain fell for five consecutive days across the county.","zh":"倾盆大雨在全县连续下了五天。","source":"ClawWords Editorial","mt":true},{"en":"However, the software was programmed such that it was nearly impossible to achieve 10 consecutive correct answers.","zh":"然而，该软件的编程方式使得几乎不可能连续获得10次正确答案。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B2","zipf":3.7,"lists":["green"]},
  {"id":"glossary","word":"glossary","ipa":"/ˈɡlɑːsəri/","senses":[{"pos":"n.","zh":"词汇表；术语汇编"}],"sceneHook":"check the glossary","sceneHookZh":"查阅词汇表","collocations":["check the glossary","technical glossary","comprehensive glossary"],"examples":[{"en":"Students can check the glossary at the back for definitions.","zh":"学生们可以查阅书后的词汇表获取定义。","source":"ClawWords Editorial","mt":true},{"en":"Each academic textbook includes a specialized glossary explaining technical terminology utilized within the text chapters.","zh":"每本学术教科书都附有一个专门的词汇表，解释各章节中使用的专业术语。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.4,"lists":["green"]},
  {"id":"consolidation","word":"consolidation","ipa":"/kənˌsɑːlɪˈdeɪʃn/","senses":[{"pos":"n.","zh":"巩固；合并"}],"sceneHook":"market consolidation","sceneHookZh":"市场整合","collocations":["market consolidation","memory consolidation","debt consolidation"],"examples":[{"en":"Recent acquisitions led to rapid market consolidation in telecommunications sectors.","zh":"近期的收购导致了电信行业快速的市场整合。","source":"ClawWords Editorial","mt":true},{"en":"Episodic memory can be thought of as a process with several different steps of memory processing: encoding, consolidation and retrieval.","zh":"情景记忆可以被视为一个包含若干不同记忆处理步骤的过程：编码、巩固和提取。","source":"IELTS","mt":true}],"color":"#22A06B","level":"C1","zipf":3.35,"lists":["green"]},
  {"id":"goodwill","word":"goodwill","ipa":"/ˌɡʊdˈwɪl/","senses":[{"pos":"n.","zh":"善意；商誉"}],"sceneHook":"gesture of goodwill","sceneHookZh":"善意姿态","collocations":["gesture of goodwill","international goodwill","company goodwill"],"examples":[{"en":"The ambassador offered assistance as a warm gesture of goodwill.","zh":"大使提供援助以作为热情的善意姿态。","source":"ClawWords Editorial","mt":true},{"en":"So, it appears that oxytocin strengthens biases, rather than promoting general goodwill, as was There were signs of these subtleties from the start.","zh":"因此，催产素似乎强化了偏见，而不是像最初所认为的那样促进了普遍的善意。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B2","zipf":3.8,"lists":["green"]},
  {"id":"sensational","word":"sensational","ipa":"/senˈseɪʃənl/","senses":[{"pos":"adj.","zh":"轰动的；引起哗然的"}],"sceneHook":"sensational headline","sceneHookZh":"轰动头条","collocations":["sensational headline","sensational victory","sensational discovery"],"examples":[{"en":"The tabloid ran a sensational headline about the movie star.","zh":"小报刊登了一条关于该电影明星的耸人听闻的头条。","source":"ClawWords Editorial","mt":true},{"en":"Media outlets often prefer sensational coverage over balanced scientific reporting to capture public attention easily.","zh":"媒体往往更喜欢轰动性的报道而非平衡的科学报道，以便轻易吸引公众注意力。","source":"IELTS","mt":true}],"color":"#16A085","level":"B2","zipf":3.75,"lists":["green"]},
  {"id":"pretension","word":"pretension","ipa":"/prɪˈtenʃn/","senses":[{"pos":"n.","zh":"虚饰；自命不凡"}],"sceneHook":"without pretension","sceneHookZh":"不矫揉造作","collocations":["without pretension","intellectual pretension","drop pretensions"],"examples":[{"en":"The chef cooked delicious meals purely without pretension or fuss.","zh":"厨师纯粹不矫揉造作、不张扬地烹制了美味佳肴。","source":"ClawWords Editorial","mt":true},{"en":"He also said, 'A woman, having fewer pretensions, is far more willing to learn.","zh":"他还说：“女性自命不凡较少，因而更加乐于学习。”","source":"IELTS","mt":true}],"color":"#2980B9","level":"C1","zipf":3,"lists":["green"]},
  {"id":"mite","word":"mite","ipa":"/maɪt/","senses":[{"pos":"n.","zh":"螨虫；微小之物"}],"sceneHook":"dust mite","sceneHookZh":"尘螨","collocations":["dust mite","microscopic mite","a mite small"],"examples":[{"en":"A common dust mite can trigger severe asthma attacks indoors.","zh":"常见的尘螨会在室内引发严重的哮喘发作。","source":"ClawWords Editorial","mt":true},{"en":"Biological researchers examined how the parasitic mite weakens honeybee colonies throughout European agricultural regions.","zh":"生物学研究人员检查了寄生螨如何削弱欧洲农业地区的蜜蜂群落。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"C1","zipf":3.1,"lists":["green"]},
  {"id":"materialistic","word":"materialistic","ipa":"/məˌtɪriəˈlɪstɪk/","senses":[{"pos":"adj.","zh":"物质主义的；追求物质享受的"}],"sceneHook":"materialistic values","sceneHookZh":"物质价值观","collocations":["materialistic values","materialistic culture","materialistic society"],"examples":[{"en":"Modern advertising often promotes shallow materialistic values to young shoppers.","zh":"现代广告往往向年轻购物者兜售肤浅的物质主义价值观。","source":"ClawWords Editorial","mt":true},{"en":"Sociologists examine whether materialistic lifestyles contribute negatively to mental well-being and long-term life satisfaction.","zh":"社会学家研究物质主义生活方式是否会对心理健康和长远生活满意度产生负面影响。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":3.45,"lists":["green"]},
  {"id":"microcosm","word":"microcosm","ipa":"/ˈmaɪkroʊkɑːzəm/","senses":[{"pos":"n.","zh":"微观世界；缩影"}],"sceneHook":"microcosm of society","sceneHookZh":"社会的缩影","collocations":["microcosm of society","perfect microcosm","microcosm of life"],"examples":[{"en":"The bustling high school served as a microcosm of society.","zh":"热闹的高中就像是整个社会的缩影。","source":"ClawWords Editorial","mt":true},{"en":"Urban planners treat this densely populated neighborhood as a fascinating microcosm of modern multicultural city living.","zh":"城市规划者将这个人口稠密的社区视为现代多元文化城市生活的引人注目的缩影。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"C1","zipf":3.05,"lists":["green"]},
  {"id":"stagnant","word":"stagnant","ipa":"/ˈstæɡnənt/","senses":[{"pos":"adj.","zh":"停滞的；污浊不流动的"}],"sceneHook":"stagnant water","sceneHookZh":"死水","collocations":["stagnant water","stagnant economy","stagnant pool"],"examples":[{"en":"Mosquitoes breed rapidly around dark pools of stagnant water outside.","zh":"蚊子在室外阴暗的死水池塘周围迅速滋生。","source":"ClawWords Editorial","mt":true},{"en":"Economists warn that persistent inflation combined with stagnant wages severely reduces purchasing power for average households.","zh":"经济学家警告称，持续通胀加上薪资停滞，严重降低了普通家庭的购买力。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B2","zipf":3.5,"lists":["green"]},
  {"id":"untrustworthy","word":"untrustworthy","ipa":"/ʌnˈtrʌstwɜːrði/","senses":[{"pos":"adj.","zh":"不可信的；靠不住的"}],"sceneHook":"untrustworthy source","sceneHookZh":"不可靠来源","collocations":["untrustworthy source","untrustworthy person","untrustworthy data"],"examples":[{"en":"Students must not cite an untrustworthy source in academic essays.","zh":"学生在学术论文中不得引用不可靠的消息来源。","source":"ClawWords Editorial","mt":true},{"en":"Financial regulators identified several untrustworthy investment schemes targeting elderly citizens with unrealistic return promises.","zh":"金融监管机构查获了几项以不切实际的回报承诺针对老年公民的不可信投资骗局。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B2","zipf":3.15,"lists":["green"]},
  {"id":"uphill","word":"uphill","ipa":"/ˌʌpˈhɪl/","senses":[{"pos":"adj.","zh":"艰辛的；上坡的"},{"pos":"adv.","zh":"向坡上"}],"sceneHook":"uphill battle","sceneHookZh":"艰苦的战斗","collocations":["uphill battle","walk uphill","uphill struggle"],"examples":[{"en":"Winning the championship proved to be an uphill battle indeed.","zh":"赢得冠军确实被证明是一场艰苦的战斗。","source":"ClawWords Editorial","mt":true},{"en":"Icelandic sourced apps and other social media and digital systems, but clearly this is going to be an uphill struggle.","zh":"冰岛本土的应用软件以及其他社交媒体和数字系统，但显然这将是一场艰苦的斗争。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.75,"lists":["green"]},
  {"id":"emboss","word":"emboss","ipa":"/ɪmˈbɔːs/","senses":[{"pos":"v.","zh":"压印浮雕；使凸起"}],"sceneHook":"emboss the logo","sceneHookZh":"压印标志","collocations":["emboss the logo","emboss leather","embossed paper"],"examples":[{"en":"Craftsmen use gold foil to emboss the logo onto leather.","zh":"工匠们用金箔将标志压印在皮革上。","source":"ClawWords Editorial","mt":true},{"en":"Printers frequently emboss raised tactile patterns onto official certificates to prevent fraudulent document duplication attempts.","zh":"印刷厂经常在官方证书上压印凸起的触觉图案，以防止伪造文件的行为。","source":"IELTS","mt":true}],"color":"#22A06B","level":"C2","zipf":2.6,"lists":["green"]},
  {"id":"internationalist","word":"internationalist","ipa":"/ˌɪntərˈnæʃnəlɪst/","senses":[{"pos":"n.","zh":"国际主义者"},{"pos":"adj.","zh":"国际主义的"}],"sceneHook":"internationalist outlook","sceneHookZh":"国际主义视野","collocations":["internationalist outlook","committed internationalist","internationalist policy"],"examples":[{"en":"The diplomat promoted an internationalist outlook throughout his long career.","zh":"这位外交官在漫长的职业生涯中倡导国际主义视野。","source":"ClawWords Editorial","mt":true},{"en":"Scholars emphasize that adopting an internationalist approach fosters cross-border scientific collaboration during global health crises.","zh":"学者强调，采取国际主义的方法有助于在全球公共卫生危机期间促进跨国科学合作。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C1","zipf":2.75,"lists":["green"]},
  {"id":"scatter","word":"scatter","ipa":"/ˈskætər/","senses":[{"pos":"v.","zh":"分散；播撒"}],"sceneHook":"scatter seeds","sceneHookZh":"播撒种子","collocations":["scatter seeds","scatter papers","clouds scatter"],"examples":[{"en":"Farmers scatter seeds across freshly ploughed fields in early spring.","zh":"农民在早春将种子撒向刚耕过的田地。","source":"ClawWords Editorial","mt":true},{"en":"As you know, the hunter-gatherer economy which existed beforehand was based on small scattered groups.","zh":"如你所知，先前存在的狩猎采集经济是以分散的小群体为基础的。","source":"IELTS","mt":true}],"color":"#16A085","level":"B1","zipf":4.1,"lists":["green"]},
  {"id":"torrent","word":"torrent","ipa":"/ˈtɔːrənt/","senses":[{"pos":"n.","zh":"洪流；倾泻"}],"sceneHook":"rushing torrent","sceneHookZh":"奔腾的急流","collocations":["rushing torrent","torrent of abuse","torrent of rain"],"examples":[{"en":"Heavy storms turned the placid creek into a rushing torrent.","zh":"暴风雨使平静的小溪变成了奔腾的急流。","source":"ClawWords Editorial","mt":true},{"en":"The unexpected cloudburst generated a violent torrent of muddy water that destroyed secondary road bridges downstream.","zh":"突如其来的暴雨形成了一股汹涌的泥流，冲毁了下游的次级公路桥梁。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.55,"lists":["green"]},
  {"id":"seam","word":"seam","ipa":"/siːm/","senses":[{"pos":"n.","zh":"接缝；矿层"}],"sceneHook":"split the seam","sceneHookZh":"裂开接缝","collocations":["split the seam","coal seam","straight seam"],"examples":[{"en":"Heavy luggage will easily split the seam of cheap fabric bags.","zh":"沉重的行李很容易撑裂廉价布包的接缝。","source":"ClawWords Editorial","mt":true},{"en":"Travel on converted mining trains and journey into the depths of the mountain along seams once worked by hundreds of miners.","zh":"乘坐改装后的采矿火车，沿着曾有数百名矿工开采过的矿层深入山体腹地。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":3.65,"lists":["green"]},
  {"id":"resit","word":"resit","ipa":"/ˈriːsɪt/","senses":[{"pos":"v.","zh":"重考；补考"},{"pos":"n.","zh":"补考"}],"sceneHook":"resit the exam","sceneHookZh":"补考","collocations":["resit the exam","examination resit","prepare to resit"],"examples":[{"en":"Failing candidates are permitted to resit the exam next autumn.","zh":"不及格的考生获准在明年秋天补考。","source":"ClawWords Editorial","mt":true},{"en":"Students who fall ill during finals may apply for permission to resit missed examinations without penalty.","zh":"期末考试期间生病的学生可以申请免受惩罚地补考缺考的科目。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":2.8,"lists":["green"]},
  {"id":"flexitime","word":"flexitime","ipa":"/ˈfleksitaɪm/","senses":[{"pos":"n.","zh":"弹性工作制"}],"sceneHook":"work on flexitime","sceneHookZh":"弹性工作","collocations":["work on flexitime","introduce flexitime","flexitime policy"],"examples":[{"en":"Office employees appreciate the opportunity to work on flexitime schedules.","zh":"办公室员工很赞赏采用弹性工作制的机会。","source":"ClawWords Editorial","mt":true},{"en":"Companies offering flexitime options report higher employee satisfaction and reduced commuting stress during peak traffic hours.","zh":"实行弹性工时制的公司报告员工满意度更高，且高峰时段的通勤压力有所减轻。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"B2","zipf":2.85,"lists":["green"]},
  {"id":"sinew","word":"sinew","ipa":"/ˈsɪnjuː/","senses":[{"pos":"n.","zh":"肌腱；筋；力量"}],"sceneHook":"strain every sinew","sceneHookZh":"竭尽全力","collocations":["strain every sinew","tough sinew","sinews of war"],"examples":[{"en":"Athletes strain every sinew to sprint across the finish line.","zh":"运动员们拼尽全力冲向终点线。","source":"ClawWords Editorial","mt":true},{"en":"Ancient archers utilized animal sinew to reinforce wooden bows, providing immense tensile strength and shot stability.","zh":"古代弓箭手利用动物肌腱来加固木弓，从而提供极大的抗拉强度和射击稳定性。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"C2","zipf":2.7,"lists":["green"]},
  {"id":"veil","word":"veil","ipa":"/veɪl/","senses":[{"pos":"n.","zh":"面纱；面罩"},{"pos":"v.","zh":"遮掩；掩饰"}],"sceneHook":"lift the veil","sceneHookZh":"揭开面纱","collocations":["lift the veil","bridal veil","veil of secrecy"],"examples":[{"en":"Scientific discoveries lift the veil on mysteries of deep space.","zh":"科学发现揭开了深空奥秘的面纱。","source":"ClawWords Editorial","mt":true},{"en":"A thick veil of sea fog blanketed the harbor, forcing maritime authorities to halt ferry services.","zh":"一层浓厚的海雾笼罩了港口，迫使海事部门暂停了轮渡服务。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B2","zipf":3.85,"lists":["green"]},
  {"id":"overdraft","word":"overdraft","ipa":"/ˈoʊvərdræft/","senses":[{"pos":"n.","zh":"透支；透支额"}],"sceneHook":"bank overdraft","sceneHookZh":"银行透支","collocations":["bank overdraft","overdraft facility","overdraft fee"],"examples":[{"en":"College students often rely on an emergency bank overdraft facility.","zh":"大学生经常依赖紧急银行透支额度。","source":"ClawWords Editorial","mt":true},{"en":"The bank charges substantial interest rates on an unauthorized overdraft balance sustained over consecutive billing cycles.","zh":"银行会对连续几个账单周期内持续存在的未经授权透支余额收取高额利息。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.1,"lists":["green"]},
  {"id":"twofold","word":"twofold","ipa":"/ˈtuːfoʊld/","senses":[{"pos":"adj.","zh":"两部分的；双重的"},{"pos":"adv.","zh":"两倍地"}],"sceneHook":"twofold increase","sceneHookZh":"两倍增长","collocations":["twofold increase","twofold purpose","twofold problem"],"examples":[{"en":"Recent surveys show a dramatic twofold increase in online retail sales.","zh":"近期调查显示在线零售额大幅增长了两倍。","source":"ClawWords Editorial","mt":true},{"en":"The primary objective of the new public transport policy was twofold: reducing carbon emissions and alleviating gridlock.","zh":"新公共交通政策的主要目的有两个：减少碳排放和缓解交通堵塞。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.65,"lists":["green"]},
  {"id":"congress","word":"congress","ipa":"/ˈkɑːŋɡrəs/","senses":[{"pos":"n.","zh":"国会；代表大会"}],"sceneHook":"act of congress","sceneHookZh":"国会法案","collocations":["act of congress","international congress","congress convenes"],"examples":[{"en":"Building national highways required a formal act of congress originally.","zh":"修建国家高速公路最初需要正式的国会法案。","source":"ClawWords Editorial","mt":true},{"en":"Medical researchers from fifty countries attended the annual cardiology congress to debate recent clinical trial outcomes.","zh":"来自五十个国家的名医研究人员出席了年度心脏病学大会，探讨近期的临床试验结果。","source":"IELTS","mt":true}],"color":"#C0392B","level":"B1","zipf":4.4,"lists":["green"]},
  {"id":"foetus","word":"foetus","ipa":"/ˈfiːtəs/","senses":[{"pos":"n.","zh":"胎儿"}],"sceneHook":"developing foetus","sceneHookZh":"发育中的胎儿","collocations":["developing foetus","human foetus","health of the foetus"],"examples":[{"en":"Maternal nutrition is critical for a healthy developing foetus indoors.","zh":"母亲的营养对室内健康发育中的胎儿至关重要。","source":"ClawWords Editorial","mt":true},{"en":"Ultrasound scans allow obstetricians to monitor the heartbeat and physical growth of the foetus during pregnancy.","zh":"超声波扫描允许产科医生在妊娠期间监测胎儿的心跳和身体生长。","source":"IELTS","mt":true}],"color":"#16A085","level":"C1","zipf":2.95,"lists":["green"]},
  {"id":"overwork","word":"overwork","ipa":"/ˌoʊvərˈwɜːrk/","senses":[{"pos":"v.","zh":"工作过度；过度劳累"},{"pos":"n.","zh":"过度工作"}],"sceneHook":"suffer from overwork","sceneHookZh":"遭受过度劳累","collocations":["suffer from overwork","avoid overwork","chronic overwork"],"examples":[{"en":"Hospital nurses frequently suffer from overwork during severe winter epidemics.","zh":"在严重的冬季流行病期间，医院护士经常苦于过度劳累。","source":"ClawWords Editorial","mt":true},{"en":"Industrial psychologists warn that chronic overwork causes severe emotional exhaustion and reduces productivity in tech sectors.","zh":"工业心理学家警告称，长期的过度工作会导致严重的情感耗竭并降低科技部门的生产力。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.35,"lists":["green"]},
  {"id":"parental","word":"parental","ipa":"/pəˈrentl/","senses":[{"pos":"adj.","zh":"父母的；亲代的"}],"sceneHook":"parental guidance","sceneHookZh":"父母的指导","collocations":["parental guidance","parental leave","parental involvement"],"examples":[{"en":"Young viewers need parental guidance when watching violent television programs.","zh":"年轻观众在观看暴力电视节目时需要父母的指导。","source":"ClawWords Editorial","mt":true},{"en":"Studies demonstrate that strong parental involvement in early literacy significantly improves long-term educational attainment for children.","zh":"研究表明，父母积极参与早期读写能显著提高儿童长期的学业成就。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":4.05,"lists":["green"]},
  {"id":"interrelationship","word":"interrelationship","ipa":"/ˌɪntərrɪˈleɪʃnʃɪp/","senses":[{"pos":"n.","zh":"相互关系；相互联系"}],"sceneHook":"complex interrelationship","sceneHookZh":"复杂相互联系","collocations":["complex interrelationship","ecological interrelationship","interrelationship between factors"],"examples":[{"en":"Biologists examine the complex interrelationship between plants and native pollinators.","zh":"生物学家研究植物与本土传粉昆虫之间复杂的相互联系。","source":"ClawWords Editorial","mt":true},{"en":"Economists study the dynamic interrelationship between rising energy costs, domestic inflation, and international trade performance.","zh":"经济学家研究能源成本上升、国内通胀与国际贸易表现之间的动态相互联系。","source":"IELTS","mt":true}],"color":"#D35400","level":"C1","zipf":2.9,"lists":["green"]},
  {"id":"incapacitate","word":"incapacitate","ipa":"/ˌɪnkəˈpæsɪteɪt/","senses":[{"pos":"v.","zh":"使丧失能力；使不能正常运转"}],"sceneHook":"incapacitate the patient","sceneHookZh":"致病患伤残","collocations":["incapacitate the patient","temporarily incapacitate","incapacitate an opponent"],"examples":[{"en":"Severe spinal fractures can permanently incapacitate the patient from walking.","zh":"严重的脊柱骨折可能会使患者永久丧失行走能力。","source":"ClawWords Editorial","mt":true},{"en":"A sudden viral infection can completely incapacitate key factory personnel, disrupting supply chains across critical industrial sectors.","zh":"突如其来的病毒感染会使关键工厂人员完全丧失工作能力，扰乱关键工业部门的供应链。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"C2","zipf":2.65,"lists":["green"]},
  {"id":"subtropical","word":"subtropical","ipa":"/ˌsʌbˈtrɑːpɪkl/","senses":[{"pos":"adj.","zh":"亚热带的"}],"sceneHook":"subtropical climate","sceneHookZh":"亚热带气候","collocations":["subtropical climate","subtropical fruit","subtropical zone"],"examples":[{"en":"Citrus groves flourish under this humid subtropical climate every winter.","zh":"柑橘林在每年冬天的这种潮湿亚热带气候下繁茂生长。","source":"ClawWords Editorial","mt":true},{"en":"The regional geography of southern China features a humid subtropical environment supporting exceptionally diverse botanical species.","zh":"中国南方的区域地理以潮湿的亚热带环境为特色，滋养了格外多样的植物物种。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B2","zipf":3.2,"lists":["green"]},
  {"id":"depress","word":"depress","ipa":"/dɪˈpres/","senses":[{"pos":"v.","zh":"使沮丧；使萧条；按下"}],"sceneHook":"depress the pedal","sceneHookZh":"踩下踏板","collocations":["depress the pedal","depress prices","depress spirits"],"examples":[{"en":"Drivers must depress the pedal smoothly to brake the car safely.","zh":"驾驶员必须平稳地踩下踏板以安全刹车。","source":"ClawWords Editorial","mt":true},{"en":"Bullying is clearly unpleasant, and can make the child experiencing it feel unworthy and depressed.","zh":"霸凌显然是令人不快的，它会让遭受霸凌的孩子感到自己没有价值且情绪低落。","source":"IELTS","mt":true}],"color":"#D9822B","level":"B2","zipf":3.75,"lists":["green"]},
  {"id":"herbivore","word":"herbivore","ipa":"/ˈhɜːrbɪvɔːr/","senses":[{"pos":"n.","zh":"草食动物"}],"sceneHook":"large herbivore","sceneHookZh":"大型草食动物","collocations":["large herbivore","grazing herbivore","herbivore diet"],"examples":[{"en":"The giant African elephant is a very famous large herbivore.","zh":"巨大的非洲象是非常著名的大型草食动物。","source":"ClawWords Editorial","mt":true},{"en":"West Indian and Amazonian manatees are both herbivores.","zh":"西印度海牛和亚马逊海牛都是草食动物。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.25,"lists":["green"]},
  {"id":"frustrate","word":"frustrate","ipa":"/ˈfrʌstreɪt/","senses":[{"pos":"v.","zh":"使沮丧；使受挫；阻挠"}],"sceneHook":"frustrate efforts","sceneHookZh":"阻碍努力","collocations":["frustrate efforts","frustrate plans","frustrate progress"],"examples":[{"en":"Bureaucratic delays often frustrate efforts to build cheaper community housing.","zh":"官僚主义的拖延往往会阻碍建设平价社区住房的努力。","source":"ClawWords Editorial","mt":true},{"en":"I know I was so frustrated at times, when we couldn't agree.","zh":"我知道有时当我们无法达成一致时，我感到非常沮丧。","source":"IELTS","mt":true}],"color":"#22A06B","level":"B2","zipf":3.7,"lists":["green"]},
  {"id":"optometrist","word":"optometrist","ipa":"/ɑːpˈtɑːmətrɪst/","senses":[{"pos":"n.","zh":"验光师；视光师"}],"sceneHook":"visit an optometrist","sceneHookZh":"看验光师","collocations":["visit an optometrist","licensed optometrist","consult an optometrist"],"examples":[{"en":"People with blurred vision should visit an optometrist for glasses.","zh":"视力模糊的人应该去看验光师配镜。","source":"ClawWords Editorial","mt":true},{"en":"A licensed optometrist conducts comprehensive eye examinations to detect early indicators of glaucoma and retinal degradation.","zh":"持有执照的验光师进行全面的眼部检查，以发现青光眼和视网膜退化的早期迹象。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C1","zipf":2.85,"lists":["green"]},
  {"id":"dissolve","word":"dissolve","ipa":"/dɪˈzɑːlv/","senses":[{"pos":"v.","zh":"溶解；解散"}],"sceneHook":"dissolve in water","sceneHookZh":"溶于水","collocations":["dissolve in water","dissolve sugar","dissolve a parliament"],"examples":[{"en":"These chemical tablets will dissolve in water within two short minutes.","zh":"这些药片将在短短两分钟内溶于水。","source":"ClawWords Editorial","mt":true},{"en":"Stirring the solution vigorously accelerates how quickly crystalline minerals dissolve under laboratory temperature controls.","zh":"剧烈搅拌溶液可在实验室温度控制下加快结晶矿物的溶解速度。","source":"IELTS","mt":true}],"color":"#16A085","level":"B1","zipf":4.15,"lists":["green"]},
  {"id":"extracurricular","word":"extracurricular","ipa":"/ˌekstrəkəˈrɪkjələr/","senses":[{"pos":"adj.","zh":"课外的"}],"sceneHook":"extracurricular clubs","sceneHookZh":"课外社团","collocations":["extracurricular clubs","extracurricular activities","extracurricular sports"],"examples":[{"en":"High schools offer various extracurricular clubs to encourage broad student participation.","zh":"高中提供各种课外社团以鼓励学生广泛参与。","source":"ClawWords Editorial","mt":true},{"en":"Admissions tutors often favor applicants who balance demanding academic workloads with meaningful extracurricular engagements.","zh":"招生导师往往青睐那些在繁重的学业与有意义的课外活动之间取得平衡的申请人。","source":"IELTS","mt":true}],"color":"#2980B9","level":"B2","zipf":3.3,"lists":["green"]},
  {"id":"propel","word":"propel","ipa":"/prəˈpel/","senses":[{"pos":"v.","zh":"推动；推进"}],"sceneHook":"propel forward","sceneHookZh":"向前推进","collocations":["propel forward","propel a boat","propel to fame"],"examples":[{"en":"Powerful twin turbines propel forward the new high-speed commuter ferry.","zh":"强大的双涡轮机推动新型高速通勤轮渡向前行驶。","source":"ClawWords Editorial","mt":true},{"en":"Innovative technological patents can propel fledgling startups into dominant market positions across competitive global sectors.","zh":"创新的技术专利能够将初创企业推向竞争激烈的全球领域中的市场主导地位。","source":"IELTS","mt":true}],"color":"#8E44AD","level":"B2","zipf":3.45,"lists":["green"]},
  {"id":"poultry","word":"poultry","ipa":"/ˈpoʊltri/","senses":[{"pos":"n.","zh":"家禽；家禽肉"}],"sceneHook":"poultry farm","sceneHookZh":"家禽养殖场","collocations":["poultry farm","poultry production","rearing poultry"],"examples":[{"en":"He worked at a large commercial poultry farm every summer holiday.","zh":"他每年暑假都在一家大型商业家禽养殖场工作。","source":"ClawWords Editorial","mt":true},{"en":"We keep goats, sheep and hens and other kinds of poultry.","zh":"我们饲养山羊、绵羊、母鸡和其他种类的家禽。","source":"IELTS","mt":true}],"color":"#D35400","level":"B2","zipf":3.55,"lists":["green"]},
  {"id":"unquote","word":"unquote","ipa":"/ˈʌnkwoʊt/","senses":[{"pos":"v.","zh":"结束引语"},{"pos":"n.","zh":"结束引语"}],"sceneHook":"quote and unquote","sceneHookZh":"引用完毕","collocations":["quote and unquote","quote unquote phrase","mark with unquote"],"examples":[{"en":"The speaker said quote and unquote to finish reading the statement.","zh":"发言人说“引用完毕”以结束朗读声明。","source":"ClawWords Editorial","mt":true},{"en":"Broadcasters frequently use the phrase quote unquote when reciting contentious official declarations verbatim during radio news bulletins.","zh":"广播员在电台新闻简报中逐字朗读有争议的官方声明时，经常使用“引用毕”这个表达。","source":"IELTS","mt":true}],"color":"#5B8DEF","level":"C1","zipf":2.75,"lists":["green"]},
  {"id":"acrobatic","word":"acrobatic","ipa":"/ˌækrəˈbætɪk/","senses":[{"pos":"adj.","zh":"杂技的；杂技般的"}],"sceneHook":"acrobatic stunts","sceneHookZh":"杂技特技","collocations":["acrobatic stunts","acrobatic troupe","acrobatic leap"],"examples":[{"en":"The circus performers thrilled audiences with daring acrobatic stunts last night.","zh":"马戏团演员昨晚以大胆的杂技特技震撼了观众。","source":"ClawWords Editorial","mt":true},{"en":"Gymnastic routines combine artistic elegance with complex acrobatic maneuvers demanding immense core physical strength.","zh":"体操动作将艺术优雅与需要极强核心体能的复杂杂技动作融为一体。","source":"IELTS","mt":true}],"color":"#2BB0A6","level":"B2","zipf":3.2,"lists":["green"]},
  {"id":"fallow","word":"fallow","ipa":"/ˈfæloʊ/","senses":[{"pos":"adj.","zh":"休耕的；休眠的"},{"pos":"n.","zh":"休耕地"}],"sceneHook":"lie fallow","sceneHookZh":"休闲轮歇","collocations":["lie fallow","fallow field","fallow land"],"examples":[{"en":"Farmers let arable fields lie fallow to replenish vital soil nutrients.","zh":"农民让耕地休耕以补充重要的土壤养分。","source":"ClawWords Editorial","mt":true},{"en":"Traditional crop rotation systems require agricultural fields to lie fallow periodically to restore essential organic soil fertility.","zh":"传统的作物轮作系统要求农田定期休耕，以恢复基本的土壤有机肥力。","source":"IELTS","mt":true}],"color":"#D9822B","level":"C1","zipf":2.95,"lists":["green"]},
  {"id":"troupe","word":"troupe","ipa":"/truːp/","senses":[{"pos":"n.","zh":"剧团；巡回演出的艺术团体"}],"sceneHook":"dance troupe","sceneHookZh":"舞蹈团","collocations":["dance troupe","theatrical troupe","circus troupe"],"examples":[{"en":"A touring dance troupe performed classical ballet at the city theatre.","zh":"一个巡回舞蹈团在市剧院表演了古典芭蕾。","source":"ClawWords Editorial","mt":true},{"en":"The renowned theatrical troupe visited several remote European towns to perform traditional Shakespearean plays outdoors.","zh":"著名的巡回剧团访问了几个偏远的欧洲城镇，在户外表演传统的莎士比亚戏剧。","source":"IELTS","mt":true}],"color":"#6C5CE7","level":"B2","zipf":3.4,"lists":["green"]},
  {"id":"discerning","word":"discerning","ipa":"/dɪˈsɜːrnɪŋ/","senses":[{"pos":"adj.","zh":"有眼光的；有鉴赏力的"}],"sceneHook":"discerning palate","sceneHookZh":"敏锐品味","collocations":["discerning palate","discerning customer","discerning eye"],"examples":[{"en":"Top restaurant critics possess a truly discerning palate for fine spices.","zh":"顶尖的餐厅评论家对优质香料有着真正敏锐的品味。","source":"ClawWords Editorial","mt":true},{"en":"Luxury fashion houses craft bespoke tailoring specifically targeted at discerning customers who appreciate fine bespoke craftsmanship.","zh":"奢侈时装品牌专门针对欣赏精致高级定制工艺的有品位顾客制作高级成衣。","source":"IELTS","mt":true}],"color":"#22A06B","level":"C1","zipf":3.35,"lists":["green"]},
  {"id":"niggle","word":"niggle","ipa":"/ˈnɪɡl/","senses":[{"pos":"v.","zh":"拘泥小节；使烦恼"},{"pos":"n.","zh":"小毛病；小烦恼"}],"sceneHook":"constant niggle","sceneHookZh":"持续的小毛病","collocations":["constant niggle","niggle about details","minor niggle"],"examples":[{"en":"A minor ankle injury remained a constant niggle throughout his season.","zh":"轻微的脚踝伤势在整个赛季中一直是一个持续的小困扰。","source":"ClawWords Editorial","mt":true},{"en":"Reviewers noted that minor typographical inconsistencies were a nagging niggle in an otherwise outstanding academic monograph.","zh":"评论人士指出，微小的印刷不一致是这本其他方面极为出色的学术专著中的一处遗憾。","source":"IELTS","mt":true}],"color":"#C0392B","level":"C2","zipf":2.7,"lists":["green"]},
  {"id":"prospectus","word":"prospectus","ipa":"/prəˈspektəs/","senses":[{"pos":"n.","zh":"简章；招贴；招股说明书"}],"sceneHook":"course prospectus","sceneHookZh":"课程简章","collocations":["course prospectus","college prospectus","investment prospectus"],"examples":[{"en":"Prospective university candidates downloaded the online course prospectus to study requirements.","zh":"未来的大学申请者下载了在线课程简章以研究录取要求。","source":"ClawWords Editorial","mt":true},{"en":"Andrew: have you seen our diploma course prospectus yet?","zh":"安德鲁：你看到我们的文凭课程简章了吗？","source":"IELTS","mt":true}],"color":"#16A085","level":"B2","zipf":3.3,"lists":["green"]}
